# Invoice Automation – Demo CRM

Demo CRM for the invoicing-automation workflow: an admin panel with **Client Management** and **Invoices** (status, manual status changes, **Retry** and **Generate now**), the CRM API the automation will call, and a mock payment gateway. Built for demonstration; the client's own system replaces it later.

Stack: Next.js 16 (App Router), PostgreSQL 17, Prisma 7 (`@prisma/adapter-pg`), Tailwind 4, shadcn/ui components, zod, jose + bcryptjs.

## Setup

```bash
npm install                 # also runs prisma generate
cp .env.example .env        # fill in DATABASE_URL, SESSION_SECRET, ADMIN_*, CRM_API_KEY
npm run db:deploy           # apply migrations (or db:migrate while developing)
npm run db:seed             # demo admin + demo clients/invoices
npm run dev                 # http://localhost:3010
```

Database user (once, as `postgres`):

```sql
CREATE ROLE invoice_demo_user LOGIN PASSWORD '...' CREATEDB;  -- CREATEDB: prisma migrate dev's shadow DB
CREATE DATABASE invoice_demo OWNER invoice_demo_user;
CREATE DATABASE invoice_demo_test OWNER invoice_demo_user;    -- integration tests (wiped on every run)
```

`npm run db:reset` drops all data and re-seeds. `npm run db:studio` opens Prisma Studio to browse the tables.

## Processing flow

`lib/invoices/processor.ts` implements the documented steps for one invoice:

1. **Claim**: `PENDING → PROCESSING` in a single guarded update; a second caller gets nothing.
2. **Gateway create**: mock gateway, idempotency key `crm-invoice-<id>`, so a retry after a crash returns the same gateway invoice.
3. **Mark CREATED** with the gateway invoice id. The write is guarded on the claim time, so a stale run cannot overwrite a newer one.
4. Sending to the client is **out of scope** for the demo.
5. **Audit log** entry for every step (`audit_logs`, append-only).

Recurring invoices: once an occurrence is CREATED, the next one is generated from its rule (weekly / monthly / quarterly / yearly, in the client's timezone; at most one successor per occurrence).

Failures: data problems (invalid email, deactivated client, no line items) are **permanent**; gateway timeouts and unexpected errors are **retryable** and get `nextRetryAt` with exponential backoff. Retries stop at `INVOICE_MAX_RETRIES`.

Admin actions: **Retry** (failed under the limit, or stuck in PROCESSING longer than `INVOICE_PROCESSING_TIMEOUT_MINUTES`), **Generate now** (pending), **Mark as paid** / **Cancel** (see `lib/invoices/transitions.ts`).

Tax (`lib/tax.ts`): QC GST 5% + QST 9.975%; HST in ON 13%, NS 14%, NB/NL/PE 15%; GST 5% elsewhere in Canada; none outside Canada.

## CRM API

All routes need `x-api-key: <CRM_API_KEY>` (or `Authorization: Bearer <key>`). Dates are UTC ISO-8601; money is a 2-decimal string.

| Method | Path | Purpose |
|---|---|---|
| GET | `/api/invoices/due?from=&to=&status=` | Invoices whose issue time is in the window. Default statuses `PENDING,FAILED,PROCESSING`: FAILED returns only retryable ones under the limit whose backoff has passed; PROCESSING returns only stuck ones. |
| POST | `/api/invoices/{id}/claim` | Atomic `PENDING → PROCESSING`. 200 when claimed, 409 when not pending. |
| PATCH | `/api/invoices/{id}/status` | Body `{ status, gatewayInvoiceId?, error?, errorType? }`. Only allowed transitions; 409 otherwise. |
| POST | `/api/invoices/{id}/log` | Body `{ result: "SUCCESS"\|"FAILURE", message, step?, metadata? }`. 201. |

```bash
curl -H "x-api-key: $CRM_API_KEY" \
  "http://localhost:3010/api/invoices/due?from=2026-10-01T00:00:00Z&to=2026-10-31T23:59:59Z"
```

## Tests

```bash
npm run test:unit           # tax, money, DST-safe recurrence, transitions, validation, auth
npm run test:integration    # against DATABASE_URL_TEST: duplicate runs, crash recovery, retries, limits, recurring, API
npm test                    # both
npm run typecheck && npm run lint
```

## Not in this demo (next phase)

Scheduler (`INVOICE_POLL_INTERVAL`), the AI agent, real payment gateway, payment webhooks, email/SMS sending, admin daily summary and developer alerts (recorded in the audit log only).
// Invoice Automation demo CRM. The CRM is the single source of truth:
// every invoice state and every processing step lives here.

generator client {
  provider = "prisma-client"
  output   = "../lib/generated/prisma"
}

datasource db {
  provider = "postgresql"
}

model Admin {
  id           Int      @id @default(autoincrement())
  name         String
  email        String   @unique
  passwordHash String
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@map("admins")
}

enum NotificationChannel {
  EMAIL
  SMS
}

model Client {
  id               Int                 @id @default(autoincrement())
  name             String
  email            String
  phone            String
  addressLine1     String
  addressLine2     String?
  city             String
  province         String // province/state code, e.g. QC, ON
  postalCode       String
  country          String              @default("CA") // ISO-3166 alpha-2
  timezone         String // IANA, e.g. America/Toronto
  preferredChannel NotificationChannel @default(EMAIL)
  smsConsent       Boolean             @default(false)
  smsConsentAt     DateTime?
  isActive         Boolean             @default(true)
  createdAt        DateTime            @default(now())
  updatedAt        DateTime            @updatedAt

  invoices       Invoice[]
  recurringRules RecurringRule[]

  @@index([isActive])
  @@map("clients")
}

enum InvoiceType {
  ONE_TIME
  RECURRING
}

enum InvoiceStatus {
  PENDING
  PROCESSING
  CREATED
  SENT
  PAID
  FAILED
  CANCELLED
}

enum ErrorType {
  RETRYABLE
  PERMANENT
}

// Demo-only switch so a presenter can show a retryable gateway failure:
// TIMEOUT fails the first attempt only, so a retry then succeeds.
// Permanent failures come from real data checks (e.g. an invalid email).
enum SimulatedFailure {
  NONE
  TIMEOUT
}

model Invoice {
  id                  Int              @id @default(autoincrement())
  invoiceNumber       String           @unique
  clientId            Int
  currency            String           @default("CAD")
  subtotal            Decimal          @db.Decimal(12, 2)
  taxTotal            Decimal          @db.Decimal(12, 2)
  total               Decimal          @db.Decimal(12, 2)
  issueAt             DateTime // UTC
  dueAt               DateTime // UTC
  paymentTerms        String // e.g. "Net 30"
  type                InvoiceType      @default(ONE_TIME)
  status              InvoiceStatus    @default(PENDING)
  retryCount          Int              @default(0)
  lastError           String?
  errorType           ErrorType?
  nextRetryAt         DateTime?
  processingStartedAt DateTime?
  gatewayInvoiceId    String?          @unique
  simulateFailure     SimulatedFailure @default(NONE)
  recurringRuleId     Int?
  parentInvoiceId     Int?             @unique // the occurrence this one was generated from
  createdAt           DateTime         @default(now())
  updatedAt           DateTime         @updatedAt

  client        Client            @relation(fields: [clientId], references: [id], onDelete: Restrict)
  lineItems     InvoiceLineItem[]
  taxes         InvoiceTax[]
  auditLogs     AuditLog[]
  recurringRule RecurringRule?    @relation(fields: [recurringRuleId], references: [id], onDelete: SetNull)
  parent        Invoice?          @relation("Occurrence", fields: [parentInvoiceId], references: [id], onDelete: SetNull)
  next          Invoice?          @relation("Occurrence")

  @@index([status, dueAt])
  @@index([clientId])
  @@map("invoices")
}

model InvoiceLineItem {
  id          Int     @id @default(autoincrement())
  invoiceId   Int
  description String
  quantity    Decimal @db.Decimal(10, 2)
  unitPrice   Decimal @db.Decimal(12, 2)
  lineTotal   Decimal @db.Decimal(12, 2)
  position    Int     @default(0)

  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)

  @@index([invoiceId])
  @@map("invoice_line_items")
}

model InvoiceTax {
  id        Int     @id @default(autoincrement())
  invoiceId Int
  name      String // GST, QST, HST
  rate      Decimal @db.Decimal(6, 3) // percent, e.g. 9.975
  amount    Decimal @db.Decimal(12, 2)

  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)

  @@index([invoiceId])
  @@map("invoice_taxes")
}

enum RecurrenceFrequency {
  WEEKLY
  MONTHLY
  QUARTERLY
  YEARLY
}

model RecurringRule {
  id              Int                 @id @default(autoincrement())
  clientId        Int
  frequency       RecurrenceFrequency
  startDate       DateTime
  endDate         DateTime?
  occurrenceCount Int? // stop after this many invoices; no endDate and no count = open-ended
  generatedCount  Int                 @default(0)
  createdAt       DateTime            @default(now())

  client   Client    @relation(fields: [clientId], references: [id], onDelete: Restrict)
  invoices Invoice[]

  @@map("recurring_rules")
}

enum AuditStep {
  CLAIM
  GATEWAY_CREATE
  STATUS_UPDATE
  RETRY
  GENERATE_NOW
  MANUAL_STATUS
  RECURRING_NEXT
  API_LOG
}

enum AuditResult {
  SUCCESS
  FAILURE
}

// Append-only: rows are never updated or deleted by the app.
model AuditLog {
  id        Int         @id @default(autoincrement())
  invoiceId Int
  step      AuditStep
  result    AuditResult
  message   String
  metadata  Json?
  actor     String // "system", "api" or "admin:<id>"
  createdAt DateTime    @default(now())

  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)

  @@index([invoiceId, createdAt])
  @@map("audit_logs")
}

// Stand-in for the payment gateway. The CRM invoice id is the idempotency
// key, so creating the same invoice twice returns the first gateway id.
model MockGatewayInvoice {
  id             Int      @id @default(autoincrement())
  idempotencyKey String   @unique
  gatewayId      String   @unique
  amount         Decimal  @db.Decimal(12, 2)
  currency       String
  createdAt      DateTime @default(now())

  @@map("mock_gateway_invoices")
}
# Copy to .env and fill in.

# PostgreSQL: app database and a separate one for the integration tests
DATABASE_URL="postgresql://invoice_demo_user:CHANGE_ME@localhost:5432/invoice_demo?schema=public"
DATABASE_URL_TEST="postgresql://invoice_demo_user:CHANGE_ME@localhost:5432/invoice_demo_test?schema=public"

# Admin session signing key (32+ characters):
#   node -e "console.log(require('crypto').randomBytes(32).toString('base64url'))"
SESSION_SECRET=""

# Demo admin created by the seeder (npm run db:seed)
ADMIN_NAME="Demo Admin"
ADMIN_EMAIL="admin@invoicedemo.test"
ADMIN_PASSWORD=""

# CRM API key for the automation (x-api-key header), 16+ characters
CRM_API_KEY=""

# Invoice processing
INVOICE_MAX_RETRIES=3
INVOICE_PROCESSING_TIMEOUT_MINUTES=15
INVOICE_RETRY_BASE_SECONDS=60
MOCK_GATEWAY_LATENCY_MS=800
# Used by the scheduler in the agent phase (5 min to 24 h); not read by the demo yet.
# INVOICE_POLL_INTERVAL=300

# Timezone for admin-facing times (audit log)
ADMIN_TIMEZONE="America/Toronto"
// Invoice-processing settings. Kept apart from the auth secrets so the
// processor, the seed script and the tests can load it on their own.

function intFromEnv(name: string, fallback: number, min: number, max: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw === "") return fallback;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new Error(`${name} must be an integer between ${min} and ${max}`);
  }
  return value;
}

export function invoiceConfig() {
  return {
    maxRetries: intFromEnv("INVOICE_MAX_RETRIES", 3, 1, 20),
    processingTimeoutMinutes: intFromEnv("INVOICE_PROCESSING_TIMEOUT_MINUTES", 15, 1, 1440),
    retryBaseSeconds: intFromEnv("INVOICE_RETRY_BASE_SECONDS", 60, 1, 86400),
    gatewayLatencyMs: intFromEnv("MOCK_GATEWAY_LATENCY_MS", 800, 0, 10000),
  };
}
import { createHash, timingSafeEqual } from "node:crypto";
import { NextResponse } from "next/server";

// The CRM API is called by the automation, not by a browser: it takes an
// API key in `x-api-key` (or `Authorization: Bearer <key>`).
// Returns an error response, or null when the key is valid.
export function requireApiKey(request: Request): NextResponse | null {
  const expected = process.env.CRM_API_KEY;
  if (!expected || expected.length < 16) {
    return NextResponse.json({ error: "CRM_API_KEY is not configured" }, { status: 500 });
  }
  const bearer = request.headers.get("authorization")?.match(/^Bearer\s+(.+)$/i)?.[1];
  const provided = request.headers.get("x-api-key") ?? bearer ?? "";
  const digest = (s: string) => createHash("sha256").update(s).digest();
  if (!provided || !timingSafeEqual(digest(provided), digest(expected))) {
    return NextResponse.json({ error: "Invalid or missing API key" }, { status: 401 });
  }
  return null;
}
import { NextResponse } from "next/server";
import { toCents, fromCents } from "@/lib/money";

// Shared helpers for the /api/invoices routes.

export function parseInvoiceId(raw: string): number | null {
  const id = Number(raw);
  return Number.isInteger(id) && id > 0 ? id : null;
}

export function badRequest(error: string, details?: unknown) {
  return NextResponse.json({ error, ...(details ? { details } : {}) }, { status: 400 });
}

export function notFoundJson() {
  return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
}

type DecimalLike = { toString(): string };

// JSON shape of an invoice: money as fixed 2-decimal strings, dates in UTC ISO.
export function serializeInvoice(invoice: {
  id: number;
  invoiceNumber: string;
  clientId: number;
  currency: string;
  subtotal: DecimalLike;
  taxTotal: DecimalLike;
  total: DecimalLike;
  issueAt: Date;
  dueAt: Date;
  paymentTerms: string;
  type: string;
  status: string;
  retryCount: number;
  lastError: string | null;
  errorType: string | null;
  nextRetryAt: Date | null;
  gatewayInvoiceId: string | null;
  recurringRuleId: number | null;
  client?: { id: number; name: string; email: string; phone: string; timezone: string; preferredChannel: string; smsConsent: boolean };
  lineItems?: { description: string; quantity: DecimalLike; unitPrice: DecimalLike; lineTotal: DecimalLike }[];
  taxes?: { name: string; rate: DecimalLike; amount: DecimalLike }[];
}) {
  const money = (v: DecimalLike) => fromCents(toCents(v));
  return {
    id: invoice.id,
    invoiceNumber: invoice.invoiceNumber,
    clientId: invoice.clientId,
    currency: invoice.currency,
    subtotal: money(invoice.subtotal),
    taxTotal: money(invoice.taxTotal),
    total: money(invoice.total),
    issueAt: invoice.issueAt.toISOString(),
    dueAt: invoice.dueAt.toISOString(),
    paymentTerms: invoice.paymentTerms,
    type: invoice.type,
    status: invoice.status,
    retryCount: invoice.retryCount,
    lastError: invoice.lastError,
    errorType: invoice.errorType,
    nextRetryAt: invoice.nextRetryAt?.toISOString() ?? null,
    gatewayInvoiceId: invoice.gatewayInvoiceId,
    recurringRuleId: invoice.recurringRuleId,
    ...(invoice.client
      ? {
          client: {
            id: invoice.client.id,
            name: invoice.client.name,
            email: invoice.client.email,
            phone: invoice.client.phone,
            timezone: invoice.client.timezone,
            preferredChannel: invoice.client.preferredChannel,
            smsConsent: invoice.client.smsConsent,
          },
        }
      : {}),
    ...(invoice.lineItems
      ? {
          lineItems: invoice.lineItems.map((l) => ({
            description: l.description,
            quantity: l.quantity.toString(),
            unitPrice: money(l.unitPrice),
            lineTotal: money(l.lineTotal),
          })),
        }
      : {}),
    ...(invoice.taxes
      ? { taxes: invoice.taxes.map((t) => ({ name: t.name, rate: t.rate.toString(), amount: money(t.amount) })) }
      : {}),
  };
}

