322	async function recordFailure(
323	  invoice: LoadedInvoice,
324	  owned: { id: number; status: "PROCESSING"; processingStartedAt: Date },
325	  err: unknown,
326	  actor: string,
327	): Promise<ProcessOutcome> {
328	  const { maxRetries, retryBaseSeconds } = invoiceConfig();
329	  // Anything that is not a known gateway error (network, DB hiccup) is
330	  // treated as temporary.
331	  const failure =
332	    err instanceof GatewayError
333	      ? err
334	      : new GatewayError(err instanceof Error ? err.message : "Unexpected error", true, "UNEXPECTED");
335	  const errorType: ErrorType = failure.retryable ? "RETRYABLE" : "PERMANENT";
336	  const retryCount = invoice.retryCount + 1;
337	  const retryLimitReached = retryCount >= maxRetries;
338	  const nextRetryAt =
339	    failure.retryable && !retryLimitReached
340	      ? new Date(Date.now() + retryDelaySeconds(retryCount, retryBaseSeconds) * 1000)
341	      : null;
342	
343	  await logStep({
344	    invoiceId: invoice.id,
345	    step: "GATEWAY_CREATE",
346	    result: "FAILURE",
347	    message: `${failure.message} [${failure.code}]`,
348	    actor,
349	    metadata: { code: failure.code, errorType },
350	  });
351	
352	  const { count } = await prisma.invoice.updateMany({
353	    where: owned,
354	    data: {
355	      status: "FAILED",
356	      retryCount: { increment: 1 },
357	      lastError: failure.message,
358	      errorType,
359	      nextRetryAt,
360	      processingStartedAt: null,
361	    },
362	  });
363	  if (count !== 1) {
364	    return { outcome: "skipped", reason: "Another run took over this invoice" };
365	  }
366	
367	  const notes = [`PROCESSING → FAILED (${errorType}, attempt ${retryCount} of ${maxRetries})`];
368	  if (errorType === "PERMANENT") notes.push("admin alert raised: the data must be fixed before a retry");
369	  if (retryLimitReached) notes.push("retry limit reached: developer alert raised");
370	  else if (nextRetryAt) notes.push(`next automatic retry after ${nextRetryAt.toISOString()}`);
371	  await logStep({
372	    invoiceId: invoice.id,
373	    step: "STATUS_UPDATE",
374	    result: "SUCCESS",
375	    message: notes.join("; "),
376	    actor,
377	    metadata: { retryCount, retryLimitReached, nextRetryAt: nextRetryAt?.toISOString() ?? null },
378	  });
379	
380	  return { outcome: "failed", error: failure.message, errorType, retryCount, retryLimitReached };
381	}
