403	      if (!ruleAllowsNext(rule, nextIssueAt)) {
404	        await logStep(
405	          {
406	            invoiceId: invoice.id,
407	            step: "RECURRING_NEXT",
408	            result: "SUCCESS",
409	            message: "Recurring schedule complete: no further occurrence",
410	            actor,
411	          },
412	          tx,
413	        );
414	        return null;
415	      }
416	
417	      const termMs = invoice.dueAt.getTime() - invoice.issueAt.getTime();
418	      const created = await tx.invoice.create({
419	        data: {
420	          invoiceNumber: `TMP-${randomUUID()}`,
421	          clientId: invoice.clientId,
422	          currency: invoice.currency,
423	          subtotal: invoice.subtotal,
424	          taxTotal: invoice.taxTotal,
425	          total: invoice.total,
426	          issueAt: nextIssueAt,
427	          dueAt: new Date(nextIssueAt.getTime() + termMs),
428	          paymentTerms: invoice.paymentTerms,
429	          type: "RECURRING",
430	          status: "PENDING",
431	          recurringRuleId: rule.id,
432	          parentInvoiceId: invoice.id,
433	          lineItems: {
