455	          invoiceId: invoice.id,
456	          step: "RECURRING_NEXT",
457	          result: "SUCCESS",
458	          message: `Next occurrence ${number} generated (issue ${nextIssueAt.toISOString()})`,
459	          actor,
460	          metadata: { nextInvoiceId: created.id },
