462	        tx,
463	      );
464	      await logStep(
465	        {
466	          invoiceId: created.id,
467	          step: "RECURRING_NEXT",
468	          result: "SUCCESS",
469	          message: `Generated from ${invoice.invoiceNumber} by the ${rule.frequency.toLowerCase()} schedule`,
470	          actor,
471	          metadata: { parentInvoiceId: invoice.id },
