510	// Next occurrence of `from`, stepped in the client's own timezone: 09:00 in
511	// Montreal stays 09:00 after a DST change, and Jan 31 + 1 month is Feb 28/29.
512	export function nextOccurrence(from: Date, frequency: RecurrenceFrequency, timeZone: string): Date {
513	  const w = wallTimeIn(from, timeZone);
514	  if (frequency === "WEEKLY") {
515	    const d = new Date(Date.UTC(w.year, w.month - 1, w.day + 7));
516	    return zonedTimeToUtc(
517	      { ...w, year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() },
518	      timeZone,
519	    );
520	  }
521	  const total = w.year * 12 + (w.month - 1) + MONTHS[frequency];
522	  const year = Math.floor(total / 12);
523	  const month = (total % 12) + 1;
524	  const day = Math.min(w.day, daysInMonth(year, month));
525	  return zonedTimeToUtc({ ...w, year, month, day }, timeZone);
526	}
