import { z } from "zod";
import { CANADIAN_PROVINCES } from "@/lib/tax";
import { isValidTimeZone } from "@/lib/timezone";

export const COUNTRIES: Record<string, string> = {
  CA: "Canada",
  US: "United States",
  GB: "United Kingdom",
  FR: "France",
  AE: "United Arab Emirates",
  PK: "Pakistan",
};

const CA_POSTAL = /^([A-Za-z]\d[A-Za-z])[ -]?(\d[A-Za-z]\d)$/;
const US_ZIP = /^\d{5}(-\d{4})?$/;

export const clientSchema = z
  .object({
    name: z.string().trim().min(2, "Name is required").max(120),
    email: z.string().trim().toLowerCase().pipe(z.email("Enter a valid email address")),
    phone: z
      .string()
      .trim()
      .regex(/^\+[1-9]\d{7,14}$/, "Use international format, e.g. +15145550123"),
    addressLine1: z.string().trim().min(3, "Address is required").max(200),
    addressLine2: z
      .string()
      .trim()
      .max(200)
      .transform((v) => (v === "" ? null : v)),
    city: z.string().trim().min(2, "City is required").max(100),
    province: z.string().trim().toUpperCase().min(2, "Province / state is required").max(50),
    postalCode: z.string().trim().min(3, "Postal code is required").max(20),
    country: z.enum(Object.keys(COUNTRIES) as [string, ...string[]], "Choose a country"),
    timezone: z.string().refine(isValidTimeZone, "Choose a valid timezone"),
    preferredChannel: z.enum(["EMAIL", "SMS"], "Choose a channel"),
    smsConsent: z.boolean(),
  })
  .superRefine((v, ctx) => {
    if (v.country === "CA") {
      if (!(v.province in CANADIAN_PROVINCES)) {
        ctx.addIssue({ code: "custom", path: ["province"], message: "Choose a Canadian province" });
      }
      if (!CA_POSTAL.test(v.postalCode)) {
        ctx.addIssue({ code: "custom", path: ["postalCode"], message: "Canadian postal code, e.g. H2X 1Y4" });
      }
    }
    if (v.country === "US" && !US_ZIP.test(v.postalCode)) {
      ctx.addIssue({ code: "custom", path: ["postalCode"], message: "US ZIP code, e.g. 10001" });
    }
    if (v.preferredChannel === "SMS" && !v.smsConsent) {
      ctx.addIssue({
        code: "custom",
        path: ["smsConsent"],
        message: "SMS as the preferred channel needs the client's SMS consent",
      });
    }
  })
  .transform((v) => {
    const m = v.country === "CA" ? CA_POSTAL.exec(v.postalCode) : null;
    return { ...v, postalCode: m ? `${m[1]} ${m[2]}`.toUpperCase() : v.postalCode };
  });

export type ClientInput = z.output<typeof clientSchema>;

export const CLIENT_FIELDS = [
  "name",
  "email",
  "phone",
  "addressLine1",
  "addressLine2",
  "city",
  "province",
  "postalCode",
  "country",
  "timezone",
  "preferredChannel",
] as const;

export type ClientFormValues = Record<(typeof CLIENT_FIELDS)[number], string> & { smsConsent: boolean };

export function readClientForm(formData: FormData): ClientFormValues {
  const values = Object.fromEntries(
    CLIENT_FIELDS.map((f) => [f, String(formData.get(f) ?? "")]),
  ) as Record<(typeof CLIENT_FIELDS)[number], string>;
  return { ...values, smsConsent: formData.get("smsConsent") === "on" };
}
"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { clientSchema, readClientForm, type ClientFormValues } from "@/lib/validation/client";

export type ClientFormState = {
  values?: ClientFormValues;
  errors?: Partial<Record<keyof ClientFormValues, string[]>>;
  message?: string;
};

function parse(formData: FormData) {
  const values = readClientForm(formData);
  const result = clientSchema.safeParse(values);
  return { values, result };
}

export async function createClientAction(_prev: ClientFormState, formData: FormData): Promise<ClientFormState> {
  await requireAdmin();
  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  const client = await prisma.client.create({
    data: { ...result.data, smsConsentAt: result.data.smsConsent ? new Date() : null },
  });
  revalidatePath("/dashboard/clients");
  redirect(`/dashboard/clients/${client.id}?saved=created`);
}

export async function updateClientAction(
  clientId: number,
  _prev: ClientFormState,
  formData: FormData,
): Promise<ClientFormState> {
  await requireAdmin();
  const existing = await prisma.client.findUnique({ where: { id: clientId } });
  if (!existing) return { message: "Client not found." };

  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  // Keep the original consent time while consent stands; record a new one
  // when it is given again; clear it when withdrawn.
  const smsConsentAt = !result.data.smsConsent
    ? null
    : existing.smsConsent
      ? existing.smsConsentAt
      : new Date();
  await prisma.client.update({ where: { id: clientId }, data: { ...result.data, smsConsentAt } });
  revalidatePath("/dashboard/clients", "layout");
  revalidatePath("/dashboard/invoices", "layout");
  redirect(`/dashboard/clients/${clientId}?saved=updated`);
}

