    { issueAt: new Date(now - 6 * DAY) },
  );
  await mustCreate(cancelled.id);
  await adminSetStatus(cancelled.id, "CANCELLED", ACTOR);

  // 12. Weekly recurring: first processed, the next one pending.
  const weekly = await createInvoice(
    c.boulangerie,
