import { revalidatePath } from "next/cache";
import { z } from "zod";
import { requireApiKey } from "@/lib/api-key";
import { badRequest, serializeInvoice } from "@/lib/api";
import { prisma } from "@/lib/db";
import { createInvoice } from "@/lib/invoices/create";
import { newInvoiceSchema } from "@/lib/validation/invoice";
import { InvoiceStatus } from "@/lib/generated/prisma/enums";
import type { Prisma } from "@/lib/generated/prisma/client";

// GET /api/invoices?status=FAILED,SENT&clientId=&updatedSince=<ISO UTC>&limit=50
// Newest change first. updatedSince lets the agent ask "what changed since
// my last run" (e.g. new failures to report).
const querySchema = z.object({
  status: z
    .string()
    .transform((s) => s.split(",").map((x) => x.trim().toUpperCase()))
    .pipe(z.array(z.enum(Object.values(InvoiceStatus) as [InvoiceStatus, ...InvoiceStatus[]])).min(1))
    .optional(),
  clientId: z.coerce.number().int().positive().optional(),
  updatedSince: z.iso.datetime({ offset: true }).optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
});

export async function GET(request: Request) {
  const denied = requireApiKey(request);
  if (denied) return denied;

  const params = Object.fromEntries(new URL(request.url).searchParams);
  const parsed = querySchema.safeParse(params);
  if (!parsed.success) return badRequest("Invalid query", z.flattenError(parsed.error).fieldErrors);
  const { status, clientId, updatedSince, limit } = parsed.data;

  const where: Prisma.InvoiceWhereInput = {
    ...(status ? { status: { in: status } } : {}),
    ...(clientId ? { clientId } : {}),
    ...(updatedSince ? { updatedAt: { gt: new Date(updatedSince) } } : {}),
  };
  const invoices = await prisma.invoice.findMany({
    where,
    orderBy: [{ updatedAt: "desc" }, { id: "desc" }],
    take: limit,
    include: { client: true },
  });
  return NextResponse.json({ count: invoices.length, invoices: invoices.map(serializeInvoice) });
}

// POST /api/invoices
// body: { clientId, lineItems: [{ description, quantity, unitPrice }], issueAt?, termsDays?,
//         recurring?: { frequency, occurrenceCount?, endDate? } }
// Adds a PENDING invoice; tax and totals come from the client's address.
export async function POST(request: Request) {
  const denied = requireApiKey(request);
  if (denied) return denied;

  const body = await request.json().catch(() => null);
  const parsed = newInvoiceSchema.safeParse(body);
  if (!parsed.success) return badRequest("Invalid body", z.flattenError(parsed.error).fieldErrors);
  const { clientId, lineItems, issueAt, termsDays, recurring } = parsed.data;

  const result = await createInvoice(
    {
      clientId,
      lineItems,
      issueAt: issueAt ? new Date(issueAt) : new Date(),
      termsDays,
      recurring: recurring && {
        frequency: recurring.frequency,
        occurrenceCount: recurring.occurrenceCount ?? null,
        endDate: recurring.endDate ? new Date(recurring.endDate) : null,
      },
    },
    "api",
  );
  if (!result.ok) {
    const status = result.error === "Client not found" ? 404 : 409;
    return NextResponse.json({ error: result.error }, { status });
  }
  revalidatePath("/dashboard/invoices", "layout");
  revalidatePath("/dashboard/clients", "layout");

  const invoice = await prisma.invoice.findUniqueOrThrow({
    where: { id: result.invoice.id },
    include: { client: true, lineItems: true, taxes: true },
  });
  return NextResponse.json({ invoice: serializeInvoice(invoice) }, { status: 201 });
}

import { NextResponse } from "next/server";
import { requireApiKey } from "@/lib/api-key";
import { notFoundJson, parseInvoiceId, serializeInvoice } from "@/lib/api";
import { prisma } from "@/lib/db";

// GET /api/invoices/{id}: the invoice with client, line items and taxes
// (what the agent needs to write the email).
export async function GET(request: Request, ctx: RouteContext<"/api/invoices/[id]">) {
  const denied = requireApiKey(request);
  if (denied) return denied;
  const id = parseInvoiceId((await ctx.params).id);
  if (!id) return notFoundJson();

  const invoice = await prisma.invoice.findUnique({
    where: { id },
    include: { client: true, lineItems: { orderBy: { position: "asc" } }, taxes: true },
  });
  if (!invoice) return notFoundJson();
  return NextResponse.json({ invoice: serializeInvoice(invoice) });
}

import { revalidatePath } from "next/cache";
import { requireApiKey } from "@/lib/api-key";
import { notFoundJson, parseInvoiceId, processResponse } from "@/lib/api";
import { processInvoice } from "@/lib/invoices/processor";

// POST /api/invoices/{id}/process: run the full flow on a PENDING invoice
// (claim → gateway → CREATED → next recurring occurrence).
// 200 with outcome "created" or "failed"; 409 when it did not run.
export async function POST(request: Request, ctx: RouteContext<"/api/invoices/[id]/process">) {
  const denied = requireApiKey(request);
  if (denied) return denied;
  const id = parseInvoiceId((await ctx.params).id);
  if (!id) return notFoundJson();

  const result = await processInvoice(id, "api");
  revalidatePath("/dashboard/invoices", "layout");
  return processResponse(id, result);
}

import { revalidatePath } from "next/cache";
import { requireApiKey } from "@/lib/api-key";
import { notFoundJson, parseInvoiceId, processResponse } from "@/lib/api";
import { retryInvoice } from "@/lib/invoices/service";

// POST /api/invoices/{id}/retry: same as the admin Retry button. Works on a
// FAILED invoice under the retry limit or one stuck in PROCESSING.
// 200 with outcome "created" or "failed"; 409 when it cannot be retried.
export async function POST(request: Request, ctx: RouteContext<"/api/invoices/[id]/retry">) {
  const denied = requireApiKey(request);
  if (denied) return denied;
  const id = parseInvoiceId((await ctx.params).id);
  if (!id) return notFoundJson();

  const result = await retryInvoice(id, "api");
  revalidatePath("/dashboard/invoices", "layout");
  return processResponse(id, result);
}

import { NextResponse } from "next/server";
import { requireApiKey } from "@/lib/api-key";
import { serializeInvoice } from "@/lib/api";
import { invoiceConfig } from "@/lib/config";
import { remindersDue } from "@/lib/invoices/reminders";

// GET /api/invoices/reminders: SENT invoices that are overdue and due for a
// reminder now (INVOICE_REMINDER_INTERVAL_DAYS apart, at most
// INVOICE_REMINDER_MAX). Claim each with POST /api/invoices/{id}/reminder
// before sending.
export async function GET(request: Request) {
  const denied = requireApiKey(request);
  if (denied) return denied;

  const { reminderIntervalDays, reminderMax } = invoiceConfig();
  const invoices = await remindersDue();
  return NextResponse.json({
    reminderIntervalDays,
    reminderMax,
    count: invoices.length,
    invoices: invoices.map(serializeInvoice),
  });
}

import { NextResponse } from "next/server";
import { revalidatePath } from "next/cache";
import { requireApiKey } from "@/lib/api-key";
import { notFoundJson, parseInvoiceId } from "@/lib/api";
import { claimReminder } from "@/lib/invoices/reminders";

// POST /api/invoices/{id}/reminder: claim the next overdue reminder before
// sending it. 200 → send the email now; 409 → none due (or another run
// already claimed it), do not send. If sending then fails, report it with
// POST /api/invoices/{id}/log (step REMINDER, result FAILURE).
export async function POST(request: Request, ctx: RouteContext<"/api/invoices/[id]/reminder">) {
  const denied = requireApiKey(request);
  if (denied) return denied;
  const id = parseInvoiceId((await ctx.params).id);
  if (!id) return notFoundJson();

  const result = await claimReminder(id, "api");
  if (!result.found) return notFoundJson();
  if (!result.claimed) return NextResponse.json({ claimed: false, error: result.reason }, { status: 409 });
  revalidatePath(`/dashboard/invoices/${id}`);
  return NextResponse.json({ claimed: true, reminderNumber: result.reminderNumber });
}

import { NextResponse } from "next/server";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { badRequest } from "@/lib/api";
import { handlePaymentEvent, verifySignature } from "@/lib/invoices/webhook";

// POST /api/webhooks/payment
// header: x-webhook-signature: sha256=<HMAC-SHA256 of the raw body with PAYMENT_WEBHOOK_SECRET>
// body:   { id, type: "invoice.paid" | "invoice.payment_failed",
//           data: { invoiceId? | gatewayInvoiceId?, reason? } }
// Repeated deliveries of the same event id are acknowledged and ignored.
const eventSchema = z.object({
  id: z.string().trim().min(1).max(200),
  type: z.enum(["invoice.paid", "invoice.payment_failed"]),
  data: z
    .object({
      invoiceId: z.number().int().positive().optional(),
      gatewayInvoiceId: z.string().trim().min(1).max(100).optional(),
      reason: z.string().trim().max(500).optional(),
    })
    .refine((d) => d.invoiceId || d.gatewayInvoiceId, "invoiceId or gatewayInvoiceId is required"),
});

export async function POST(request: Request) {
  const secret = process.env.PAYMENT_WEBHOOK_SECRET;
  if (!secret || secret.length < 16) {
    return NextResponse.json({ error: "PAYMENT_WEBHOOK_SECRET is not configured" }, { status: 500 });
  }
  const raw = await request.text();
  if (!verifySignature(raw, request.headers.get("x-webhook-signature"), secret)) {
    return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
  }

  let body: unknown = null;
  try {
    body = JSON.parse(raw);
  } catch {
    return badRequest("Body must be JSON");
  }
  const parsed = eventSchema.safeParse(body);
  if (!parsed.success) return badRequest("Invalid event", z.flattenError(parsed.error));

  const result = await handlePaymentEvent(parsed.data);
  if (!result.found) return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
  revalidatePath("/dashboard/invoices", "layout");
  revalidatePath("/dashboard/clients", "layout");
  return NextResponse.json({ received: true, ...result });
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { requireApiKey } from "@/lib/api-key";
import { badRequest } from "@/lib/api";
import { prisma } from "@/lib/db";

// GET /api/clients?search=<name or email>&includeInactive=true
// Lets the agent find the client an invoice is for.
const querySchema = z.object({
  search: z.string().trim().max(100).optional(),
  includeInactive: z.enum(["true", "false"]).default("false"),
});

export async function GET(request: Request) {
  const denied = requireApiKey(request);
  if (denied) return denied;

  const params = Object.fromEntries(new URL(request.url).searchParams);
  const parsed = querySchema.safeParse(params);
  if (!parsed.success) return badRequest("Invalid query", z.flattenError(parsed.error).fieldErrors);
  const { search, includeInactive } = parsed.data;

  const clients = await prisma.client.findMany({
    where: {
      ...(includeInactive === "true" ? {} : { isActive: true }),
      ...(search
        ? {
            OR: [
              { name: { contains: search, mode: "insensitive" } },
              { email: { contains: search, mode: "insensitive" } },
            ],
          }
        : {}),
    },
    orderBy: { name: "asc" },
    take: 50,
  });
  return NextResponse.json({
    count: clients.length,
    clients: clients.map((c) => ({
      id: c.id,
      name: c.name,
      email: c.email,
      phone: c.phone,
      city: c.city,
      province: c.province,
      country: c.country,
      timezone: c.timezone,
      preferredChannel: c.preferredChannel,
      isActive: c.isActive,
    })),
  });
}

