import Link from "next/link";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { invoiceConfig } from "@/lib/config";
import { formatMoney, fromCents, toCents } from "@/lib/money";
import { formatInZone } from "@/lib/timezone";
import { STATUS_LABELS } from "@/lib/format";
import { actionFlags } from "@/lib/invoices/service";
import { cn } from "@/lib/utils";
import type { Prisma } from "@/lib/generated/prisma/client";
import { InvoiceStatus } from "@/lib/generated/prisma/enums";
import { PageHeader } from "@/components/layout/PageHeader";
import { Pagination } from "@/components/layout/Pagination";
import { StatusBadge } from "@/components/invoices/StatusBadge";
import { InvoiceActions } from "@/components/invoices/InvoiceActions";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

const PAGE_SIZE = 15;
const STATUSES = Object.values(InvoiceStatus);

function one(v: string | string[] | undefined): string | undefined {
  return Array.isArray(v) ? v[0] : v;
}

export default async function InvoicesPage(props: PageProps<"/dashboard/invoices">) {
  await requireAdmin();
  const sp = await props.searchParams;
  const status = STATUSES.find((s) => s === one(sp.status));
  const q = one(sp.q)?.trim() || undefined;
  const page = Math.max(1, Number(one(sp.page)) || 1);
  const { maxRetries } = invoiceConfig();

  const where: Prisma.InvoiceWhereInput = {
    ...(status ? { status } : {}),
    ...(q
      ? {
          OR: [
            { invoiceNumber: { contains: q, mode: "insensitive" } },
            { client: { name: { contains: q, mode: "insensitive" } } },
          ],
        }
      : {}),
  };

  const [invoices, total, byStatus] = await Promise.all([
    prisma.invoice.findMany({
      where,
      include: { client: { select: { id: true, name: true, timezone: true } } },
      orderBy: [{ issueAt: "desc" }, { id: "desc" }],
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
    }),
    prisma.invoice.count({ where }),
    prisma.invoice.groupBy({
      by: ["status", "currency"],
      _count: { _all: true },
      _sum: { total: true },
    }),
  ]);

  // Live stats straight from the database. Counts cover every invoice;
  // amounts add up CAD invoices only, since currencies cannot be summed.
  const count = (s: InvoiceStatus) =>
    byStatus.filter((b) => b.status === s).reduce((acc, b) => acc + b._count._all, 0);
  const sum = (ss: InvoiceStatus[]) =>
    fromCents(
      byStatus
        .filter((b) => b.currency === "CAD" && ss.includes(b.status))
        .reduce((acc, b) => acc + toCents(b._sum.total ?? 0), 0),
    );
  const allCount = byStatus.reduce((acc, b) => acc + b._count._all, 0);

  const cards = [
    { label: "All invoices", value: allCount, href: "/dashboard/invoices", active: !status },
    ...STATUSES.map((s) => ({
      label: STATUS_LABELS[s],
      value: count(s),
      href: `/dashboard/invoices?status=${s}`,
      active: status === s,
    })),
  ];

  return (
    <>
      <PageHeader
        title="Invoices"
        description="Every invoice in the CRM with its processing status. Failed invoices can be retried; pending ones can be generated now."
      />

      <div className="mb-4 grid grid-cols-2 gap-3 sm:grid-cols-4 xl:grid-cols-8">
        {cards.map((c) => (
          <Link
            key={c.label}
            href={c.href}
            className={cn(
              "rounded-lg border bg-card px-4 py-3 hover:border-primary/40",
              c.active && "border-primary ring-1 ring-primary",
            )}
          >
            <p className="text-xs text-muted-foreground">{c.label}</p>
            <p className="mt-1 text-2xl font-semibold tabular-nums">{c.value}</p>
          </Link>
        ))}
      </div>
      <div className="mb-6 grid gap-3 sm:grid-cols-3">
        <Stat label="Outstanding, CAD (created + sent)" value={formatMoney(sum(["CREATED", "SENT"]), "CAD")} />
        <Stat label="Collected, CAD (paid)" value={formatMoney(sum(["PAID"]), "CAD")} />
        <Stat label="Failed, CAD (needs attention)" value={formatMoney(sum(["FAILED"]), "CAD")} tone="danger" />
      </div>

      <div className="rounded-lg border bg-card">
        <form className="flex flex-wrap items-center gap-2 border-b p-4" action="/dashboard/invoices">
          <Input name="q" defaultValue={q} placeholder="Search invoice # or client" className="max-w-xs" />
          <select
            name="status"
            defaultValue={status ?? ""}
            className="h-10 rounded-md border border-input bg-background px-3 text-sm"
          >
            <option value="">All statuses</option>
            {STATUSES.map((s) => (
              <option key={s} value={s}>
                {STATUS_LABELS[s]}
              </option>
            ))}
          </select>
          <Button type="submit" variant="secondary">
            Filter
          </Button>
          {(q || status) && (
            <Link href="/dashboard/invoices" className="text-sm text-muted-foreground hover:underline">
              Clear
            </Link>
          )}
        </form>

        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Invoice</TableHead>
              <TableHead>Client</TableHead>
              <TableHead className="text-right">Total</TableHead>
              <TableHead>Issue date</TableHead>
              <TableHead>Due date</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-center">Retries</TableHead>
              <TableHead>Last error</TableHead>
              <TableHead>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {invoices.length === 0 && (
              <TableRow>
                <TableCell colSpan={10} className="py-10 text-center text-muted-foreground">
                  No invoices match these filters.
                </TableCell>
              </TableRow>
            )}
            {invoices.map((inv) => {
              const flags = actionFlags(inv);
              return (
                <TableRow key={inv.id}>
                  <TableCell>
                    <Link href={`/dashboard/invoices/${inv.id}`} className="font-medium text-primary hover:underline">
                      {inv.invoiceNumber}
                    </Link>
                  </TableCell>
                  <TableCell>
                    <Link href={`/dashboard/clients/${inv.client.id}`} className="hover:underline">
                      {inv.client.name}
                    </Link>
                  </TableCell>
                  <TableCell className="text-right tabular-nums">{formatMoney(inv.total, inv.currency)}</TableCell>
                  <TableCell className="whitespace-nowrap">
                    {formatInZone(inv.issueAt, inv.client.timezone, false)}
                  </TableCell>
                  <TableCell className="whitespace-nowrap">
                    {formatInZone(inv.dueAt, inv.client.timezone, false)}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground">
                    {inv.type === "RECURRING" ? "Recurring" : "One-time"}
                  </TableCell>
                  <TableCell>
                    <StatusBadge status={inv.status} stuck={flags.stuck} />
                  </TableCell>
                  <TableCell className="text-center tabular-nums">
                    {inv.retryCount}/{maxRetries}
                  </TableCell>
                  <TableCell className="max-w-56 truncate text-xs text-red-700" title={inv.lastError ?? ""}>
                    {inv.lastError ?? <span className="text-muted-foreground">—</span>}
                  </TableCell>
                  <TableCell>
                    {flags.canRetry || flags.canGenerate ? (
                      <InvoiceActions
                        invoiceId={inv.id}
                        invoiceNumber={inv.invoiceNumber}
                        canRetry={flags.canRetry}
                        canGenerate={flags.canGenerate}
                        compact
                      />
                    ) : (
                      <Link href={`/dashboard/invoices/${inv.id}`} className="text-sm text-primary hover:underline">
                        View
                      </Link>
                    )}
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
        <Pagination
          page={page}
          pageCount={Math.ceil(total / PAGE_SIZE)}
          total={total}
          basePath="/dashboard/invoices"
          params={{ q, status }}
        />
      </div>
    </>
  );
}

function Stat({ label, value, tone }: { label: string; value: string; tone?: "danger" }) {
  return (
    <div className="rounded-lg border bg-card px-4 py-3">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className={cn("mt-1 text-lg font-semibold tabular-nums", tone === "danger" && "text-red-700")}>{value}</p>
    </div>
  );
}
