  const message = await prisma.emailMessage.create({
    data: {
      invoiceId,
      direction: "INBOUND",
      kind: "CLIENT_MESSAGE",
      toAddress: addressOf(emailConfig().from),
      fromAddress: inv.client.email,
      subject: `Re: Invoice ${inv.invoiceNumber}`,
      body: body.trim(),
      delivery: "RECEIVED",
