  if (!inv) return { ok: false, error: "Invoice not found" };
  const { adminAlertEmail, appUrl } = agentConfig();
  const { maxRetries } = invoiceConfig();
  if (!adminAlertEmail) return { ok: false, error: "No admin email is configured (ADMIN_ALERT_EMAIL / ADMIN_EMAIL)" };

  const email = await sendEmail({
    invoiceId,
    kind: "ALERT",
    to: adminAlertEmail,
    subject: `[Invoice failed] ${inv.invoiceNumber} (${inv.client.name})`,
