    }
    return true;
  }
}

import { readConfig } from "./config";
import { CrmClient } from "./crm";
import { TaskRunner } from "./runner";

// Long-running worker: npm run agent:worker (Ctrl+C to stop).
// Polls the CRM for agent tasks and queues overdue reminders periodically.

const cfg = readConfig();
const runner = new TaskRunner(cfg, new CrmClient(cfg));
let stopping = false;
process.on("SIGINT", () => {
  if (stopping) process.exit(1);
  stopping = true;
  console.log("\nStopping after the current task (Ctrl+C again to force)...");
});

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function main() {
  console.log(`Invoice agent worker: CRM ${cfg.crmBaseUrl}, agent ${cfg.agentId}, polling every ${cfg.pollSeconds}s`);
  let lastReminderCheck = 0;
  while (!stopping) {
    try {
      if (Date.now() - lastReminderCheck >= cfg.reminderCheckMinutes * 60_000) {
        const queued = await runner.enqueueReminders();
        if (queued > 0) console.log(`Queued ${queued} overdue reminder(s)`);
        lastReminderCheck = Date.now();
      }
      const didWork = await runner.runNext();
      if (!didWork) await sleep(cfg.pollSeconds * 1000);
    } catch (err) {
      console.error(`Worker error: ${err instanceof Error ? err.message : err}`);
      await sleep(cfg.pollSeconds * 1000);
    }
  }
}

main().then(() => process.exit(0));

import { readConfig } from "./config";
import { CrmClient } from "./crm";
import { TaskRunner } from "./runner";

// Testing helper: npm run agent:once
// Queues due reminders, runs every pending task, then exits.

async function main() {
  const cfg = readConfig();
  const runner = new TaskRunner(cfg, new CrmClient(cfg));
  const queued = await runner.enqueueReminders();
  if (queued > 0) console.log(`Queued ${queued} overdue reminder(s)`);
  let count = 0;
  while (await runner.runNext()) count++;
  console.log(count === 0 ? "No pending agent tasks." : `\nRan ${count} task(s).`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

import Anthropic from "@anthropic-ai/sdk";
import { readConfig } from "./config";
import { CrmClient } from "./crm";

// npm run agent:check - verifies the setup without sending any email or
// starting a session: .env values, the CRM, the agent and environment.

async function main() {
  const cfg = readConfig();
  let ok = true;
  const pass = (msg: string) => console.log(`✔ ${msg}`);
  const fail = (msg: string) => {
    ok = false;
    console.log(`✖ ${msg}`);
  };

  try {
    const r = await new CrmClient(cfg).call<{ count?: number }>("GET", "/api/invoices?limit=1");
    if (r.status === 200) pass(`CRM reachable at ${cfg.crmBaseUrl} and CRM_API_KEY accepted`);
    else fail(`CRM answered ${r.status}`);
  } catch (err) {
    fail(err instanceof Error ? err.message : String(err));
  }

  const client = new Anthropic();
  try {
    const agent = await client.beta.agents.retrieve(cfg.agentId);
    const model = typeof agent.model === "string" ? agent.model : agent.model.id;
    const tools = agent.tools.map((t) => ("name" in t ? t.name : t.type)).join(", ");
    pass(`Agent "${agent.name}" (${agent.id}, version ${agent.version}, model ${model})`);
    console.log(`    tools: ${tools}`);
  } catch (err) {
    fail(`Agent ${cfg.agentId}: ${err instanceof Error ? err.message : err}`);
  }
  try {
    const env = await client.beta.environments.retrieve(cfg.environmentId);
    pass(`Environment "${env.name}" (${env.id})`);
  } catch (err) {
    fail(`Environment ${cfg.environmentId}: ${err instanceof Error ? err.message : err}`);
  }

  const provider = process.env.EMAIL_PROVIDER === "resend" ? "resend" : "outbox";
  if (provider === "resend" && !process.env.RESEND_API_KEY) fail("EMAIL_PROVIDER=resend but RESEND_API_KEY is empty");
  else
    pass(
      provider === "resend"
        ? `Emails go out through Resend${process.env.EMAIL_TEST_RECIPIENT ? `, all redirected to ${process.env.EMAIL_TEST_RECIPIENT}` : ""}`
        : "Emails stay in the CRM outbox (EMAIL_PROVIDER is not resend)",
    );
  console.log(`  Session budget: $${(cfg.sessionBudgetCents / 100).toFixed(2)} per invoice`);

  console.log(ok ? "\nAll good." : "\nFix the items marked ✖ and run again.");
  process.exit(ok ? 0 : 1);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

import "dotenv/config";
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import path from "node:path";

// Runs the `ant` CLI with ANTHROPIC_API_KEY taken from .env, so the key
// never has to be exported in your shell:  npm run agent:plan / agent:apply

function antBinary(): string {
  if (process.env.ANT_BIN) return process.env.ANT_BIN;
  const local = process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, "Programs", "ant", "ant.exe");
  return local && existsSync(local) ? local : "ant";
}

if (!process.env.ANTHROPIC_API_KEY) {
  console.error("ANTHROPIC_API_KEY is not set in .env");
  process.exit(1);
}
const result = spawnSync(antBinary(), process.argv.slice(2), { stdio: "inherit", env: process.env });
if (result.error) {
  console.error(`Could not run ant: ${result.error.message}. Install it (see docs/MANAGED_AGENT_PLAN.md).`);
  process.exit(1);
}
process.exit(result.status ?? 1);

