import Link from "next/link";
import { Plus } from "lucide-react";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import type { Prisma } from "@/lib/generated/prisma/client";
import { PageHeader } from "@/components/layout/PageHeader";
import { Pagination } from "@/components/layout/Pagination";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

const PAGE_SIZE = 15;

function one(v: string | string[] | undefined): string | undefined {
  return Array.isArray(v) ? v[0] : v;
}

export default async function ClientsPage(props: PageProps<"/dashboard/clients">) {
  await requireAdmin();
  const sp = await props.searchParams;
  const q = one(sp.q)?.trim() || undefined;
  const state = one(sp.state) === "inactive" ? "inactive" : one(sp.state) === "all" ? "all" : "active";
  const page = Math.max(1, Number(one(sp.page)) || 1);

  const where: Prisma.ClientWhereInput = {
    ...(state === "all" ? {} : { isActive: state === "active" }),
    ...(q
      ? {
          OR: [
            { name: { contains: q, mode: "insensitive" } },
            { email: { contains: q, mode: "insensitive" } },
            { city: { contains: q, mode: "insensitive" } },
          ],
        }
      : {}),
  };

  const [clients, total] = await Promise.all([
    prisma.client.findMany({
      where,
      include: { _count: { select: { invoices: true } } },
      orderBy: { name: "asc" },
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
    }),
    prisma.client.count({ where }),
  ]);

  return (
    <>
      <PageHeader
        title="Client Management"
        description="Billing details, timezone and notification preferences used when invoices are processed."
        actions={
          <Button asChild>
            <Link href="/dashboard/clients/new">
              <Plus /> Add client
            </Link>
          </Button>
        }
      />

      <div className="rounded-lg border bg-card">
        <form className="flex flex-wrap items-center gap-2 border-b p-4" action="/dashboard/clients">
          <Input name="q" defaultValue={q} placeholder="Search name, email or city" className="max-w-xs" />
          <select
            name="state"
            defaultValue={state}
            className="h-10 rounded-md border border-input bg-background px-3 text-sm"
          >
            <option value="active">Active</option>
            <option value="inactive">Deactivated</option>
            <option value="all">All</option>
          </select>
          <Button type="submit" variant="secondary">
            Filter
          </Button>
        </form>

        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Name</TableHead>
              <TableHead>Email</TableHead>
              <TableHead>Phone</TableHead>
              <TableHead>Location</TableHead>
              <TableHead>Timezone</TableHead>
              <TableHead>Channel</TableHead>
              <TableHead>SMS consent</TableHead>
              <TableHead className="text-center">Invoices</TableHead>
              <TableHead>Status</TableHead>
              <TableHead />
            </TableRow>
          </TableHeader>
          <TableBody>
            {clients.length === 0 && (
              <TableRow>
                <TableCell colSpan={10} className="py-10 text-center text-muted-foreground">
                  No clients found.
                </TableCell>
              </TableRow>
            )}
            {clients.map((c) => (
              <TableRow key={c.id}>
                <TableCell>
                  <Link href={`/dashboard/clients/${c.id}`} className="font-medium text-primary hover:underline">
                    {c.name}
                  </Link>
                </TableCell>
                <TableCell>{c.email}</TableCell>
                <TableCell className="whitespace-nowrap">{c.phone}</TableCell>
                <TableCell className="whitespace-nowrap">
                  {c.city}, {c.province} · {c.country}
                </TableCell>
                <TableCell className="text-xs text-muted-foreground">{c.timezone}</TableCell>
                <TableCell>{c.preferredChannel === "SMS" ? "SMS" : "Email"}</TableCell>
                <TableCell>{c.smsConsent ? "Yes" : "No"}</TableCell>
                <TableCell className="text-center tabular-nums">{c._count.invoices}</TableCell>
                <TableCell>
                  <span
                    className={
                      c.isActive
                        ? "rounded-full bg-emerald-50 px-2 py-0.5 text-xs text-emerald-700"
                        : "rounded-full bg-zinc-100 px-2 py-0.5 text-xs text-zinc-500"
                    }
                  >
                    {c.isActive ? "Active" : "Deactivated"}
                  </span>
                </TableCell>
                <TableCell>
                  <Link href={`/dashboard/clients/${c.id}/edit`} className="text-sm text-primary hover:underline">
                    Edit
                  </Link>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
        <Pagination
          page={page}
          pageCount={Math.ceil(total / PAGE_SIZE)}
          total={total}
          basePath="/dashboard/clients"
          params={{ q, state: state === "active" ? undefined : state }}
        />
      </div>
    </>
  );
}
import Link from "next/link";
import { cn } from "@/lib/utils";

// Prev / next links that keep the current filters in the query string.
export function Pagination({
  page,
  pageCount,
  total,
  basePath,
  params,
}: {
  page: number;
  pageCount: number;
  total: number;
  basePath: string;
  params: Record<string, string | undefined>;
}) {
  const href = (p: number) => {
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) if (v) q.set(k, v);
    if (p > 1) q.set("page", String(p));
    const s = q.toString();
    return s ? `${basePath}?${s}` : basePath;
  };
  const link = (p: number, label: string, disabled: boolean) => (
    <Link
      href={disabled ? "#" : href(p)}
      aria-disabled={disabled}
      className={cn(
        "rounded-md border px-3 py-1.5 text-sm",
        disabled ? "pointer-events-none text-muted-foreground opacity-50" : "hover:bg-accent",
      )}
    >
      {label}
    </Link>
  );
  return (
    <div className="flex items-center justify-between border-t px-4 py-3 text-sm text-muted-foreground">
      <span>
        {total} result{total === 1 ? "" : "s"} · page {page} of {Math.max(pageCount, 1)}
      </span>
      <div className="flex gap-2">
        {link(page - 1, "Previous", page <= 1)}
        {link(page + 1, "Next", page >= pageCount)}
      </div>
    </div>
  );
}
// Fallback shown while a dashboard page checks the session and loads its
// data. Each page folder has its own loading.tsx using it: on a client
// navigation the dashboard layout stays mounted, so only a boundary inside
// the page's own segment can show.
export function PageSkeleton() {
  return (
    <div className="space-y-4" aria-busy="true" aria-label="Loading">
      <div className="h-7 w-48 rounded bg-muted" />
      <div className="h-4 w-80 rounded bg-muted" />
      <div className="h-64 rounded-lg border bg-card" />
    </div>
  );
}
import { cn } from "@/lib/utils";
import { STATUS_LABELS } from "@/lib/format";
import type { InvoiceStatus } from "@/lib/generated/prisma/enums";

const STYLES: Record<InvoiceStatus, string> = {
  PENDING: "bg-slate-100 text-slate-700 ring-slate-200",
