import Link from "next/link";
import { ArrowLeft, UserPlus } from "lucide-react";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { PageHeader } from "@/components/layout/PageHeader";
import { NewInvoiceForm } from "@/components/invoices/NewInvoiceForm";
import { Button } from "@/components/ui/button";

export default async function NewInvoicePage() {
  await requireAdmin();
  const clients = await prisma.client.findMany({
    where: { isActive: true },
    orderBy: { name: "asc" },
    select: { id: true, name: true, email: true, country: true, province: true, city: true },
  });

  return (
    <>
      <Link
        href="/dashboard/invoices"
        className="mb-3 inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
      >
        <ArrowLeft className="size-4" /> All invoices
      </Link>
      <PageHeader
        title="New invoice"
        description="Add the items and choose one-time or recurring billing. Tax is worked out from the client's address."
      />
      {clients.length === 0 ? (
        <div className="surface flex flex-col items-center gap-3 px-6 py-16 text-center">
          <UserPlus className="size-8 text-muted-foreground" />
          <p className="font-medium">Add a client first</p>
          <p className="max-w-sm text-sm text-muted-foreground">Invoices are billed to a client. Create one, then come back here.</p>
          <Button asChild className="mt-2">
            <Link href="/dashboard/clients/new">Add client</Link>
          </Button>
        </div>
      ) : (
        <NewInvoiceForm clients={clients} />
      )}
    </>
  );
}

