p='app/dashboard/invoices/actions.ts'
s=open(p,encoding='utf-8').read()
a='''import { recordClientMessage, resolveEscalation } from "@/lib/agent/emails";
'''
b='''import { recordClientMessage, resolveEscalation } from "@/lib/agent/emails";
import { redirect } from "next/navigation";
import { prisma } from "@/lib/db";
import { createInvoice } from "@/lib/invoices/create";
import { lineItemSchema } from "@/lib/validation/invoice";
import { wallTimeIn, zonedTimeToUtc } from "@/lib/timezone";
import { RecurrenceFrequency } from "@/lib/generated/prisma/enums";
'''
assert s.count(a)==1; s=s.replace(a,b)
s+='''
// New invoice from the dashboard form. An issue date of today (or earlier)
// is processed right away, so the assistant emails it within moments; a
// future date is left PENDING for the schedule to pick up on that day.
const newInvoiceFormSchema = z.object({
  clientId: z.number({ error: "Choose a client" }).int().positive("Choose a client"),
  issueDate: z.string().regex(/^\\d{4}-\\d{2}-\\d{2}$/, "Choose an issue date"),
  termsDays: z.number().int().min(0).max(365),
  lineItems: z.array(lineItemSchema).min(1, "Add at least one item").max(50),
  recurring: z
    .object({
      frequency: z.enum(Object.values(RecurrenceFrequency) as [RecurrenceFrequency, ...RecurrenceFrequency[]]),
      occurrenceCount: z.number().int().min(1, "At least 1").max(500).nullable(),
    })
    .nullable(),
});

export type NewInvoiceInput = z.input<typeof newInvoiceFormSchema>;
export type NewInvoiceResult = { ok: false; message: string; fieldErrors?: Record<string, string> };

export async function createInvoiceAction(input: NewInvoiceInput): Promise<NewInvoiceResult> {
  const admin = await requireAdmin();
  const actor = `admin:${admin.id}`;
  const parsed = newInvoiceFormSchema.safeParse(input);
  if (!parsed.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of parsed.error.issues) fieldErrors[issue.path.join(".")] ??= issue.message;
    return { ok: false, message: "Please fix the highlighted fields.", fieldErrors };
  }
  const data = parsed.data;
  const client = await prisma.client.findUnique({ where: { id: data.clientId }, select: { timezone: true } });
  if (!client) return { ok: false, message: "Client not found" };

  const now = new Date();
  const today = wallTimeIn(now, client.timezone);
  const todayKey = `${today.year}-${String(today.month).padStart(2, "0")}-${String(today.day).padStart(2, "0")}`;
  const [y, m, d] = data.issueDate.split("-").map(Number);
  const issueAt =
    data.issueDate <= todayKey ? now : zonedTimeToUtc({ year: y, month: m, day: d, hour: 9, minute: 0, second: 0 }, client.timezone);

  const result = await createInvoice(
    {
      clientId: data.clientId,
      lineItems: data.lineItems,
      issueAt,
      termsDays: data.termsDays,
      recurring: data.recurring
        ? { frequency: data.recurring.frequency, occurrenceCount: data.recurring.occurrenceCount, endDate: null }
        : undefined,
    },
    actor,
  );
  if (!result.ok) return { ok: false, message: result.error };

  if (issueAt <= now) await generateNow(result.invoice.id, actor);
  revalidatePath("/dashboard/invoices");
  revalidatePath("/dashboard/clients", "layout");
  redirect(`/dashboard/invoices/${result.invoice.id}?created=1`);
}
'''
open(p,'w',encoding='utf-8',newline='\n').write(s)
