"use client";

import { useMemo, useState, useTransition } from "react";
import { toast } from "sonner";
import { CalendarClock, Loader2, Plus, Repeat, Send, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { computeTotals, taxLinesFor } from "@/lib/tax";
import { formatMoney, fromCents } from "@/lib/money";
import { cn } from "@/lib/utils";
import { createInvoiceAction } from "@/app/dashboard/invoices/actions";

type ClientOption = { id: number; name: string; email: string; country: string; province: string; city: string };
type Line = { description: string; quantity: string; unitPrice: string };
type Frequency = "WEEKLY" | "MONTHLY" | "QUARTERLY" | "YEARLY";

const TERMS = [
  { value: 0, label: "Due on receipt" },
  { value: 7, label: "Net 7" },
  { value: 15, label: "Net 15" },
  { value: 30, label: "Net 30" },
  { value: 45, label: "Net 45" },
  { value: 60, label: "Net 60" },
];

const FREQUENCIES: { value: Frequency; label: string }[] = [
  { value: "WEEKLY", label: "Every week" },
  { value: "MONTHLY", label: "Every month" },
  { value: "QUARTERLY", label: "Every 3 months" },
  { value: "YEARLY", label: "Every year" },
];

const today = () => new Date().toLocaleDateString("en-CA"); // YYYY-MM-DD, local
const num = (v: string) => (v.trim() === "" ? NaN : Number(v));

export function NewInvoiceForm({ clients }: { clients: ClientOption[] }) {
  const [clientId, setClientId] = useState<number | "">("");
  const [issueDate, setIssueDate] = useState(today);
  const [termsDays, setTermsDays] = useState(30);
  const [recurring, setRecurring] = useState(false);
  const [frequency, setFrequency] = useState<Frequency>("MONTHLY");
  const [count, setCount] = useState("12");
  const [lines, setLines] = useState<Line[]>([{ description: "", quantity: "1", unitPrice: "" }]);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [pending, startTransition] = useTransition();

  const client = clients.find((c) => c.id === clientId);
  const currency = client?.country === "US" ? "USD" : "CAD";
  const money = (cents: number) => formatMoney(fromCents(cents), currency);

  const totals = useMemo(() => {
    const valid = lines
      .map((l) => ({ quantity: num(l.quantity), unitPriceCents: Math.round(num(l.unitPrice) * 100) }))
      .map((l) => (Number.isFinite(l.quantity) && Number.isFinite(l.unitPriceCents) ? l : { quantity: 0, unitPriceCents: 0 }));
    return computeTotals(valid, client ? taxLinesFor(client.country, client.province) : []);
  }, [lines, client]);

  const scheduled = issueDate > today();
  const setLine = (i: number, patch: Partial<Line>) => setLines((ls) => ls.map((l, j) => (j === i ? { ...l, ...patch } : l)));

  const submit = () => {
    setErrors({});
    startTransition(async () => {
      try {
        const r = await createInvoiceAction({
          clientId: clientId === "" ? 0 : clientId,
          issueDate,
          termsDays,
          lineItems: lines.map((l) => ({ description: l.description, quantity: num(l.quantity), unitPrice: num(l.unitPrice) })),
          recurring: recurring ? { frequency, occurrenceCount: count.trim() === "" ? null : Number(count) } : null,
        });
        // Success redirects; anything that returns is an error.
        if (r && !r.ok) {
          setErrors(r.fieldErrors ?? {});
          toast.error(r.message);
        }
      } catch (err) {
        if (err && typeof err === "object" && "digest" in err && String(err.digest).startsWith("NEXT_REDIRECT")) throw err;
        toast.error("Could not create the invoice. Check that you are still signed in.");
      }
    });
  };

  const err = (key: string) => errors[key] && <p className="mt-1 text-xs text-red-600">{errors[key]}</p>;

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_340px]">
      <div className="space-y-6">
        <section className="surface p-6">
          <h2 className="text-base font-semibold">Client &amp; dates</h2>
          <div className="mt-5 grid gap-5 sm:grid-cols-3">
            <div className="sm:col-span-3">
              <Label htmlFor="client">Bill to</Label>
              <select
                id="client"
                className="select mt-2 w-full"
                value={clientId}
                onChange={(e) => setClientId(e.target.value ? Number(e.target.value) : "")}
              >
                <option value="">Choose a client…</option>
                {clients.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name} · {c.email}
                  </option>
                ))}
              </select>
              {client && (
                <p className="mt-1.5 text-xs text-muted-foreground">
                  {client.city}, {client.province} · {client.country} · billed in {currency}
                </p>
              )}
              {err("clientId")}
            </div>
            <div>
              <Label htmlFor="issueDate">Issue date</Label>
              <Input
                id="issueDate"
                type="date"
                className="mt-2"
                min={today()}
                value={issueDate}
                onChange={(e) => setIssueDate(e.target.value)}
              />
              {err("issueDate")}
            </div>
            <div>
              <Label htmlFor="terms">Payment terms</Label>
              <select id="terms" className="select mt-2 w-full" value={termsDays} onChange={(e) => setTermsDays(Number(e.target.value))}>
                {TERMS.map((t) => (
                  <option key={t.value} value={t.value}>
                    {t.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </section>

        <section className="surface p-6">
          <h2 className="text-base font-semibold">Billing</h2>
          <div className="mt-4 inline-flex rounded-lg border bg-muted p-1">
            {[
              { value: false, label: "One-time" },
              { value: true, label: "Recurring" },
            ].map((o) => (
              <button
                key={o.label}
                type="button"
                onClick={() => setRecurring(o.value)}
                className={cn(
                  "rounded-md px-4 py-1.5 text-sm font-medium transition-colors",
                  recurring === o.value ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground",
                )}
              >
                {o.label}
              </button>
            ))}
          </div>
          {recurring && (
            <div className="mt-5 grid gap-5 sm:grid-cols-2">
              <div>
                <Label htmlFor="frequency">Repeat</Label>
                <select
                  id="frequency"
                  className="select mt-2 w-full"
                  value={frequency}
                  onChange={(e) => setFrequency(e.target.value as Frequency)}
                >
                  {FREQUENCIES.map((f) => (
                    <option key={f.value} value={f.value}>
                      {f.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <Label htmlFor="count">Number of invoices</Label>
                <Input
                  id="count"
                  type="number"
                  min={1}
                  className="mt-2"
                  value={count}
                  placeholder="Leave empty to keep going"
                  onChange={(e) => setCount(e.target.value)}
                />
                {err("recurring.occurrenceCount")}
              </div>
            </div>
          )}
        </section>

        <section className="surface p-6">
          <h2 className="text-base font-semibold">Items</h2>
          <div className="mt-4 hidden grid-cols-[1fr_90px_130px_110px_36px] gap-3 px-1 text-[11px] font-semibold tracking-wider text-muted-foreground uppercase sm:grid">
            <span>Description</span>
            <span>Qty</span>
            <span>Unit price</span>
            <span className="text-right">Amount</span>
            <span />
          </div>
          <div className="mt-2 space-y-3">
            {lines.map((l, i) => (
              <div key={i} className="grid grid-cols-2 gap-3 sm:grid-cols-[1fr_90px_130px_110px_36px] sm:items-start">
                <div className="col-span-2 sm:col-span-1">
                  <Input
                    aria-label="Description"
                    placeholder="e.g. Website maintenance, October"
                    value={l.description}
                    onChange={(e) => setLine(i, { description: e.target.value })}
                  />
                  {err(`lineItems.${i}.description`)}
                </div>
                <div>
                  <Input
                    aria-label="Quantity"
                    type="number"
                    min={0}
                    step="0.01"
                    value={l.quantity}
                    onChange={(e) => setLine(i, { quantity: e.target.value })}
                  />
                  {err(`lineItems.${i}.quantity`)}
                </div>
                <div>
                  <Input
                    aria-label="Unit price"
                    type="number"
                    min={0}
                    step="0.01"
                    placeholder="0.00"
                    value={l.unitPrice}
                    onChange={(e) => setLine(i, { unitPrice: e.target.value })}
                  />
                  {err(`lineItems.${i}.unitPrice`)}
                </div>
                <p className="flex h-10 items-center justify-end text-sm font-medium tabular-nums">
                  {money(totals.lines[i]?.lineTotalCents ?? 0)}
                </p>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-10 text-muted-foreground hover:text-red-600"
                  disabled={lines.length === 1}
                  onClick={() => setLines((ls) => ls.filter((_, j) => j !== i))}
                  aria-label="Remove item"
                >
                  <Trash2 />
                </Button>
              </div>
            ))}
          </div>
          {err("lineItems")}
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="mt-4"
            onClick={() => setLines((ls) => [...ls, { description: "", quantity: "1", unitPrice: "" }])}
          >
            <Plus /> Add item
          </Button>
        </section>
      </div>

      <aside className="lg:sticky lg:top-24 lg:self-start">
        <section className="surface p-6">
          <h2 className="text-base font-semibold">Summary</h2>
          <dl className="mt-4 space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-muted-foreground">Subtotal</dt>
              <dd className="tabular-nums">{money(totals.subtotalCents)}</dd>
            </div>
            {totals.taxes.map((t) => (
              <div key={t.name} className="flex justify-between">
                <dt className="text-muted-foreground">
                  {t.name} ({t.ratePercent}%)
                </dt>
                <dd className="tabular-nums">{money(t.amountCents)}</dd>
              </div>
            ))}
            {client && totals.taxes.length === 0 && <p className="text-xs text-muted-foreground">No Canadian sales tax for this client.</p>}
            <div className="flex items-baseline justify-between border-t pt-3">
              <dt className="font-medium">Total</dt>
              <dd className="text-2xl font-semibold tracking-tight tabular-nums">{money(totals.totalCents)}</dd>
            </div>
          </dl>
          <div className="mt-5 flex gap-2.5 rounded-lg bg-indigo-50 p-3 text-xs leading-relaxed text-indigo-900">
            {scheduled ? (
              <CalendarClock className="mt-0.5 size-4 shrink-0" />
            ) : recurring ? (
              <Repeat className="mt-0.5 size-4 shrink-0" />
            ) : (
              <Send className="mt-0.5 size-4 shrink-0" />
            )}
            <p>
              {scheduled
                ? "Scheduled: the invoice is created and emailed automatically on the issue date."
                : "The invoice is created now and your assistant emails it to the client within a minute."}
              {recurring && " Each next invoice in the series is created automatically."}
            </p>
          </div>
          <Button className="mt-5 w-full" size="lg" disabled={pending} onClick={submit}>
            {pending ? <Loader2 className="animate-spin" /> : <Send />}
            {scheduled ? "Schedule invoice" : "Create & send invoice"}
          </Button>
        </section>
      </aside>
    </div>
  );
}

