                    step="0.01"
                    placeholder="0.00"
                    value={l.unitPrice}
                    onChange={(e) => setLine(i, { unitPrice: e.target.value })}
                  />
                  {err(`lineItems.${i}.unitPrice`)}
                </div>
                <p className="flex h-10 items-center justify-end text-sm font-medium tabular-nums">
                  {money(totals.lines[i]?.lineTotalCents ?? 0)}
                </p>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-10 text-muted-foreground hover:text-red-600"
                  disabled={lines.length === 1}
                  onClick={() => setLines((ls) => ls.filter((_, j) => j !== i))}
                  aria-label="Remove item"
                >
                  <Trash2 />
                </Button>
              </div>
            ))}
          </div>
          {err("lineItems")}
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="mt-4"
            onClick={() => setLines((ls) => [...ls, { description: "", quantity: "1", unitPrice: "" }])}
          >
            <Plus /> Add item
          </Button>
        </section>
      </div>

      <aside className="lg:sticky lg:top-24 lg:self-start">
        <section className="surface p-6">
          <h2 className="text-base font-semibold">Summary</h2>
          <dl className="mt-4 space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-muted-foreground">Subtotal</dt>
              <dd className="tabular-nums">{money(totals.subtotalCents)}</dd>
            </div>
            {totals.taxes.map((t) => (
              <div key={t.name} className="flex justify-between">
                <dt className="text-muted-foreground">
                  {t.name} ({t.ratePercent}%)
                </dt>
                <dd className="tabular-nums">{money(t.amountCents)}</dd>
              </div>
            ))}
            {client && totals.taxes.length === 0 && <p className="text-xs text-muted-foreground">No Canadian sales tax for this client.</p>}
            <div className="flex items-baseline justify-between border-t pt-3">
              <dt className="font-medium">Total</dt>
              <dd className="text-2xl font-semibold tracking-tight tabular-nums">{money(totals.totalCents)}</dd>
            </div>
          </dl>
          <div className="mt-5 flex gap-2.5 rounded-lg bg-indigo-50 p-3 text-xs leading-relaxed text-indigo-900">
            {scheduled ? (
              <CalendarClock className="mt-0.5 size-4 shrink-0" />
            ) : recurring ? (
              <Repeat className="mt-0.5 size-4 shrink-0" />
            ) : (
              <Send className="mt-0.5 size-4 shrink-0" />
            )}
            <p>
              {scheduled
                ? "Scheduled: the invoice is created and emailed automatically on the issue date."
                : "The invoice is created now and your assistant emails it to the client within a minute."}
              {recurring && " Each next invoice in the series is created automatically."}
            </p>
          </div>
          <Button className="mt-5 w-full" size="lg" disabled={pending} onClick={submit}>
            {pending ? <Loader2 className="animate-spin" /> : <Send />}
            {scheduled ? "Schedule invoice" : "Create & send invoice"}
          </Button>
        </section>
      </aside>
    </div>
  );
}

