content.content:
1	import { Resend } from "resend";
2	import { prisma } from "@/lib/db";
3	import { emailConfig } from "@/lib/config";
4	import type { EmailMessage } from "@/lib/generated/prisma/client";
5	import type { EmailKind } from "@/lib/generated/prisma/enums";
6	
7	// Every email is first written to email_messages (the outbox). With
8	// EMAIL_PROVIDER=resend it is then handed to Resend and the row records the
9	// outcome. A delivery failure never throws: callers read `delivery`.
10	
11	export type OutgoingEmail = {
12	  invoiceId: number;
13	  kind: EmailKind;
14	  to: string;
15	  subject: string;
16	  body: string;
17	};
18	
19	/** Plain address out of "Name <a@b.c>". */
20	export function addressOf(from: string): string {
21	  return from.match(/<([^>]+)>/)?.[1] ?? from;
22	}
23	
24	export async function sendEmail(email: OutgoingEmail): Promise<EmailMessage> {
25	  const cfg = emailConfig();
26	  const deliveredTo = cfg.testRecipient ?? email.to;
27	  const row = await prisma.emailMessage.create({
28	    data: {
29	      invoiceId: email.invoiceId,
