export async function escalateToAdmin(invoiceId: number, input: EscalationInput, actor: string): Promise<AgentActionResult> {
  const inv = await loadInvoice(invoiceId);
  if (!inv) return { ok: false, error: "Invoice not found" };
  const { adminAlertEmail, appUrl } = agentConfig();
  if (!adminAlertEmail) return { ok: false, error: "No admin email is configured (ADMIN_ALERT_EMAIL / ADMIN_EMAIL)" };

  await prisma.invoice.update({ where: { id: invoiceId }, data: { needsAttention: true, escalatedAt: new Date() } });
  const email = await sendEmail({
    invoiceId,
    kind: "ESCALATION",
    to: adminAlertEmail,
    subject: `[Action needed] ${input.category} - ${inv.invoiceNumber} (${inv.client.name})`,
    body: [
      `The invoice agent escalated a client conversation (${input.category}).`,
      "",
      `Summary: ${input.summary}`,
      ...(input.clientRequest ? ["", `What the client asks: ${input.clientRequest}`] : []),
      ...(input.recommendedAction ? ["", `Suggested next step: ${input.recommendedAction}`] : []),
      "",
      `Invoice: ${inv.invoiceNumber}, ${formatMoney(inv.total, inv.currency)} ${inv.currency}, status ${inv.status}`,
      `Client: ${inv.client.name} <${inv.client.email}>`,
      `Open in the CRM: ${appUrl}/dashboard/invoices/${inv.id}`,
    ].join("\n"),
  });
  await logStep({
    invoiceId,
    step: "ESCALATION",
    result: "SUCCESS",
    message: `Escalated to admin (${input.category}): ${input.summary.slice(0, 300)}${
      email.delivery === "FAILED" ? ` [admin email failed: ${email.error}]` : ""
    }`,
    actor,
    metadata: { emailId: email.id, category: input.category },
  });
  return { ok: true, emailId: email.id, message: "Escalated to the admin. The invoice is flagged as needing attention." };
