// Plain code, no agent.
export async function sendFailureAlert(invoiceId: number, actor: string): Promise<AgentActionResult> {
  const inv = await prisma.invoice.findUnique({ where: { id: invoiceId }, include: { client: true } });
  if (!inv) return { ok: false, error: "Invoice not found" };
  const { adminAlertEmail, appUrl } = agentConfig();
  const { maxRetries } = invoiceConfig();
  if (!adminAlertEmail) return { ok: false, error: "No admin email is configured (ADMIN_ALERT_EMAIL / ADMIN_EMAIL)" };

  const email = await sendEmail({
    invoiceId,
    kind: "ALERT",
    to: adminAlertEmail,
    subject: `[Invoice failed] ${inv.invoiceNumber} (${inv.client.name})`,
    body: [
      `Invoice ${inv.invoiceNumber} for ${inv.client.name} failed to process.`,
      "",
      `Error: ${inv.lastError ?? "unknown"}`,
      `Type: ${inv.errorType === "PERMANENT" ? "permanent - fix the data, then press Retry" : "temporary"}`,
      `Attempts: ${inv.retryCount} of ${maxRetries}${inv.retryCount >= maxRetries ? " (retry limit reached)" : ""}`,
      "",
      `Open in the CRM: ${appUrl}/dashboard/invoices/${inv.id}`,
    ].join("\n"),
  });
  if (email.delivery === "FAILED") return { ok: false, error: `Alert email failed: ${email.error}` };
  await logStep({
    invoiceId,
    step: "EMAIL_SENT",
    result: "SUCCESS",
    message: `Failure alert sent to the admin (${adminAlertEmail})`,
    actor,
    metadata: { emailId: email.id },
  });
  return { ok: true, emailId: email.id, message: "Failure alert sent to the admin." };
}

