const RULE = "----------------------------------------";

// The CRM's own summary under every invoice and reminder email.
function invoiceBlock(inv: LoadedInvoice, heading: string): string {
  const money = (v: { toString(): string }) => formatMoney(v, inv.currency);
  const tz = inv.client.timezone;
  return [
    RULE,
    `${heading}: ${inv.invoiceNumber} - ${inv.client.name}`,
    `Issue date: ${formatInZone(inv.issueAt, tz, false)} | Due date: ${formatInZone(inv.dueAt, tz, false)} (${inv.paymentTerms})`,
    "",
    ...inv.lineItems.map(
      (l) => `  ${l.description}: ${Number(l.quantity)} x ${money(l.unitPrice)} = ${money(l.lineTotal)}`,
    ),
    "",
    `Subtotal: ${money(inv.subtotal)}`,
    ...inv.taxes.map((t) => `${t.name} (${Number(t.rate)}%): ${money(t.amount)}`),
    `Total due: ${money(inv.total)} ${inv.currency}`,
    "",
    `Pay online: ${paymentLink(inv.id)}`,
    RULE,
  ].join("\n");
}

function receiptBlock(inv: LoadedInvoice): string {
  return [
    RULE,
    `Payment receipt: ${inv.invoiceNumber} - ${inv.client.name}`,
    `Amount paid: ${formatMoney(inv.total, inv.currency)} ${inv.currency}`,
    `Paid on: ${inv.paidAt ? formatInZone(inv.paidAt, inv.client.timezone) : "-"}`,
    RULE,
  ].join("\n");
}

function replyFooter(inv: LoadedInvoice): string {
  const lines = [RULE, `Regarding invoice ${inv.invoiceNumber} (${formatMoney(inv.total, inv.currency)} ${inv.currency}, ${inv.status.toLowerCase()})`];
  if (PAYABLE.includes(inv.status)) lines.push(`Pay online: ${paymentLink(inv.id)}`);
  lines.push(RULE);
  return lines.join("\n");
}

