import { notFound } from "next/navigation";
import { CheckCircle2, Info } from "lucide-react";
import { prisma } from "@/lib/db";
import { agentConfig } from "@/lib/config";
import { formatMoney } from "@/lib/money";
import { formatInZone } from "@/lib/timezone";
import { PayButton } from "./PayButton";

// Public mock payment page (no login): the link in the invoice email.
// No real money moves; paying marks the invoice PAID in the CRM.
export default async function PayPage(props: PageProps<"/pay/[id]">) {
  const { id: rawId } = await props.params;
  const id = Number(rawId);
  if (!Number.isInteger(id) || id <= 0) notFound();

  const invoice = await prisma.invoice.findUnique({
    where: { id },
    include: {
      client: { select: { name: true, timezone: true } },
      lineItems: { orderBy: { position: "asc" } },
      taxes: true,
    },
  });
  if (!invoice) notFound();

  const { businessName } = agentConfig();
  const tz = invoice.client.timezone;
  const money = (v: { toString(): string }) => formatMoney(v, invoice.currency);
  const payable = invoice.status === "CREATED" || invoice.status === "SENT";

  return (
    <main className="flex min-h-screen items-start justify-center bg-muted/40 px-4 py-10">
      <div className="w-full max-w-lg space-y-4">
        <div className="flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">
          <Info className="mt-0.5 size-4 shrink-0" />
          <p>Demo payment page. No card is charged and no real money moves.</p>
        </div>

        <section className="surface shadow-sm">
          <header className="border-b px-6 py-5">
            <p className="text-sm text-muted-foreground">{businessName}</p>
            <h1 className="mt-1 text-xl font-semibold">Invoice {invoice.invoiceNumber}</h1>
            <p className="text-sm text-muted-foreground">
              Billed to {invoice.client.name} · Due {formatInZone(invoice.dueAt, tz, false)}
            </p>
          </header>

          <div className="space-y-2 px-6 py-4 text-sm">
            {invoice.lineItems.map((l) => (
              <div key={l.id} className="flex justify-between gap-4">
                <span>
                  {l.description}
                  <span className="text-muted-foreground"> × {Number(l.quantity)}</span>
                </span>
                <span className="tabular-nums">{money(l.lineTotal)}</span>
              </div>
            ))}
          </div>

          <dl className="space-y-1 border-t px-6 py-4 text-sm">
            <Row label="Subtotal" value={money(invoice.subtotal)} />
            {invoice.taxes.map((t) => (
              <Row key={t.id} label={`${t.name} (${Number(t.rate)}%)`} value={money(t.amount)} />
            ))}
            <Row label={`Total (${invoice.currency})`} value={money(invoice.total)} strong />
          </dl>

          <div className="border-t px-6 py-5">
            {invoice.status === "PAID" ? (
              <div className="flex items-start gap-2 text-emerald-700">
                <CheckCircle2 className="mt-0.5 size-5 shrink-0" />
                <div>
                  <p className="font-medium">Paid{invoice.paidAt ? ` on ${formatInZone(invoice.paidAt, tz)}` : ""}</p>
                  <p className="text-sm text-muted-foreground">Thank you. A receipt is emailed to you.</p>
                </div>
              </div>
            ) : payable ? (
              <PayButton invoiceId={invoice.id} label={`Pay ${money(invoice.total)} (mock)`} />
            ) : (
              <p className="text-sm text-muted-foreground">
                This invoice cannot be paid online (status: {invoice.status.toLowerCase()}).
              </p>
            )}
          </div>
        </section>
      </div>
    </main>
  );
}

function Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div className="flex justify-between gap-4">
      <dt className="text-muted-foreground">{label}</dt>
      <dd className={`tabular-nums ${strong ? "font-semibold" : ""}`}>{value}</dd>
    </div>
  );
}

