import { requireAdmin } from "@/lib/auth/session";
import { PageHeader } from "@/components/layout/PageHeader";
import { ClientForm } from "@/components/clients/ClientForm";
import { createClientAction } from "../actions";

export default async function NewClientPage() {
  await requireAdmin();
  return (
    <div className="max-w-3xl">
      <PageHeader title="Add client" description="All fields come from the invoicing specification." />
      <ClientForm action={createClientAction} cancelHref="/dashboard/clients" submitLabel="Create client" />
    </div>
  );
}
import { notFound } from "next/navigation";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { PageHeader } from "@/components/layout/PageHeader";
import { ClientForm } from "@/components/clients/ClientForm";
import { updateClientAction } from "../../actions";

export default async function EditClientPage(props: PageProps<"/dashboard/clients/[id]/edit">) {
  await requireAdmin();
  const id = Number((await props.params).id);
  if (!Number.isInteger(id) || id <= 0) notFound();
  const client = await prisma.client.findUnique({ where: { id } });
  if (!client) notFound();

  return (
    <div className="max-w-3xl">
      <PageHeader title={`Edit ${client.name}`} />
      <ClientForm
        action={updateClientAction.bind(null, client.id)}
        cancelHref={`/dashboard/clients/${client.id}`}
        submitLabel="Save changes"
        initial={{
          name: client.name,
          email: client.email,
          phone: client.phone,
          addressLine1: client.addressLine1,
          addressLine2: client.addressLine2 ?? "",
          city: client.city,
          province: client.province,
          postalCode: client.postalCode,
          country: client.country,
          timezone: client.timezone,
          preferredChannel: client.preferredChannel,
          smsConsent: client.smsConsent,
        }}
      />
    </div>
  );
}

export async function setClientActiveAction(
  clientId: number,
  active: boolean,
): Promise<{ ok: boolean; message: string }> {
  await requireAdmin();
  const id = z.number().int().positive().parse(clientId);
  const { count } = await prisma.client.updateMany({ where: { id }, data: { isActive: active } });
  if (count !== 1) return { ok: false, message: "Client not found." };
  revalidatePath("/dashboard/clients", "layout");
  return {
    ok: true,
    message: active ? "Client reactivated." : "Client deactivated. Their invoices will not be processed.",
  };
}

