import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft, Pencil } from "lucide-react";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { formatMoney } from "@/lib/money";
import { formatInZone } from "@/lib/timezone";
import { formatAdminTime } from "@/lib/format";
import { CANADIAN_PROVINCES, taxLinesFor } from "@/lib/tax";
import { COUNTRIES } from "@/lib/validation/client";
import { PageHeader } from "@/components/layout/PageHeader";
import { StatusBadge } from "@/components/invoices/StatusBadge";
import { ClientActiveToggle } from "@/components/clients/ClientActiveToggle";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

export default async function ClientPage(props: PageProps<"/dashboard/clients/[id]">) {
  await requireAdmin();
  const id = Number((await props.params).id);
  if (!Number.isInteger(id) || id <= 0) notFound();
  const sp = await props.searchParams;

  const client = await prisma.client.findUnique({
    where: { id },
    include: { invoices: { orderBy: [{ issueAt: "desc" }, { id: "desc" }] } },
  });
  if (!client) notFound();

  const taxes = taxLinesFor(client.country, client.province);
  const saved = sp.saved === "created" ? "Client created." : sp.saved === "updated" ? "Changes saved." : null;

  return (
    <>
      <Link
        href="/dashboard/clients"
        className="mb-3 inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
      >
        <ArrowLeft className="size-4" /> All clients
      </Link>
      <PageHeader
        title={client.name}
        description={client.isActive ? "Active client" : "Deactivated: invoices are not processed"}
        actions={
          <>
            <Button asChild variant="outline">
              <Link href={`/dashboard/clients/${client.id}/edit`}>
                <Pencil /> Edit
              </Link>
            </Button>
            <ClientActiveToggle clientId={client.id} name={client.name} isActive={client.isActive} />
          </>
        }
      />
      {saved && (
        <p className="mb-4 rounded-md bg-emerald-50 px-3 py-2 text-sm text-emerald-800">{saved}</p>
      )}

      <div className="grid gap-6 lg:grid-cols-3">
        <section className="surface p-4">
          <h2 className="mb-3 text-sm font-semibold">Details</h2>
          <dl className="space-y-2 text-sm">
            <Row label="Email" value={client.email} />
            <Row label="Phone" value={client.phone} />
            <Row
              label="Address"
              value={
                <>
                  {client.addressLine1}
                  {client.addressLine2 && <>, {client.addressLine2}</>}
                  <br />
                  {client.city}, {CANADIAN_PROVINCES[client.province] ?? client.province} {client.postalCode}
                  <br />
                  {COUNTRIES[client.country] ?? client.country}
                </>
              }
            />
            <Row label="Timezone" value={client.timezone} />
            <Row label="Preferred channel" value={client.preferredChannel === "SMS" ? "SMS" : "Email"} />
            <Row
              label="SMS consent"
              value={client.smsConsent && client.smsConsentAt ? `Yes, since ${formatAdminTime(client.smsConsentAt)}` : "No"}
            />
            <Row
              label="Sales tax"
              value={taxes.length ? taxes.map((t) => `${t.name} ${t.ratePercent}%`).join(" + ") : "None (outside Canada)"}
            />
          </dl>
        </section>

        <section className="surface lg:col-span-2">
          <h2 className="border-b px-4 py-3 text-sm font-semibold">Invoices ({client.invoices.length})</h2>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Invoice</TableHead>
"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { clientSchema, readClientForm, type ClientFormValues } from "@/lib/validation/client";

export type ClientFormState = {
  values?: ClientFormValues;
  errors?: Partial<Record<keyof ClientFormValues, string[]>>;
  message?: string;
};

function parse(formData: FormData) {
  const values = readClientForm(formData);
  const result = clientSchema.safeParse(values);
  return { values, result };
}

export async function createClientAction(_prev: ClientFormState, formData: FormData): Promise<ClientFormState> {
  await requireAdmin();
  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  const client = await prisma.client.create({
    data: { ...result.data, smsConsentAt: result.data.smsConsent ? new Date() : null },
  });
  revalidatePath("/dashboard/clients");
  redirect(`/dashboard/clients/${client.id}?saved=created`);
}

export async function updateClientAction(
  clientId: number,
  _prev: ClientFormState,
  formData: FormData,
): Promise<ClientFormState> {
  await requireAdmin();
  const existing = await prisma.client.findUnique({ where: { id: clientId } });
  if (!existing) return { message: "Client not found." };

  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  // Keep the original consent time while consent stands; record a new one
  // when it is given again; clear it when withdrawn.
  const smsConsentAt = !result.data.smsConsent
    ? null
    : existing.smsConsent
      ? existing.smsConsentAt
      : new Date();
  await prisma.client.update({ where: { id: clientId }, data: { ...result.data, smsConsentAt } });
  revalidatePath("/dashboard/clients", "layout");
  revalidatePath("/dashboard/invoices", "layout");
  redirect(`/dashboard/clients/${clientId}?saved=updated`);
}

