"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/db";
import { requireAdmin } from "@/lib/auth/session";
import { clientSchema, readClientForm, type ClientFormValues } from "@/lib/validation/client";

export type ClientFormState = {
  values?: ClientFormValues;
  errors?: Partial<Record<keyof ClientFormValues, string[]>>;
  message?: string;
};

function parse(formData: FormData) {
  const values = readClientForm(formData);
  const result = clientSchema.safeParse(values);
  return { values, result };
}

export async function createClientAction(_prev: ClientFormState, formData: FormData): Promise<ClientFormState> {
  await requireAdmin();
  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  const client = await prisma.client.create({
    data: { ...result.data, smsConsentAt: result.data.smsConsent ? new Date() : null },
  });
  revalidatePath("/dashboard/clients");
  redirect(`/dashboard/clients/${client.id}?saved=created`);
}

export async function updateClientAction(
  clientId: number,
  _prev: ClientFormState,
  formData: FormData,
): Promise<ClientFormState> {
  await requireAdmin();
  const existing = await prisma.client.findUnique({ where: { id: clientId } });
  if (!existing) return { message: "Client not found." };

  const { values, result } = parse(formData);
  if (!result.success) {
    return { values, errors: z.flattenError(result.error).fieldErrors, message: "Please fix the highlighted fields." };
  }
  // Keep the original consent time while consent stands; record a new one
  // when it is given again; clear it when withdrawn.
  const smsConsentAt = !result.data.smsConsent
    ? null
    : existing.smsConsent
      ? existing.smsConsentAt
      : new Date();
  await prisma.client.update({ where: { id: clientId }, data: { ...result.data, smsConsentAt } });
  revalidatePath("/dashboard/clients", "layout");
  revalidatePath("/dashboard/invoices", "layout");
  redirect(`/dashboard/clients/${clientId}?saved=updated`);
}

