// UI end-to-end check against the test server (no emails: the worker is not running).
import { chromium } from "playwright-core";

const BASE = "http://localhost:3012";
const OUT = new URL(".", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const shot = (page, name) => page.screenshot({ path: `${OUT}${name}.png`, fullPage: true });
const log = (...a) => console.log("•", ...a);

const browser = await chromium.launch({ channel: "msedge", headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on("pageerror", (e) => console.log("PAGE ERROR:", e.message));

try {
  // 1. Login
  await page.goto(`${BASE}/login`);
  await shot(page, "01-login");
  await page.fill("#email", "admin@ledgerly.app");
  await page.fill("#password", "Ledgerly@2026");
  await page.click("button[type=submit]");
  await page.waitForURL("**/dashboard/invoices");
  log("login ok ->", page.url());
  await shot(page, "02-invoices-empty");

  async function addClient(c) {
    await page.goto(`${BASE}/dashboard/clients/new`);
    await page.fill("#name", c.name);
    await page.fill("#email", c.email);
    await page.fill("#phone", c.phone);
    await page.selectOption("#timezone", c.timezone);
    await page.fill("#addressLine1", c.address);
    await page.fill("#city", c.city);
    await page.selectOption("#country", c.country);
    if (c.country === "CA") await page.selectOption("#province", c.province);
    else await page.fill("#province", c.province);
    await page.fill("#postalCode", c.postal);
    await page.click(`button:has-text("${c.type === "MONTHLY" ? "Recurring (monthly)" : "One-time"}")`);
    await page.fill("#billingDescription", c.service);
    await page.fill("#billingAmount", c.amount);
    if (c.date) await page.fill("#billingDate", c.date);
    if (c.shot) await shot(page, c.shot);
    await page.click('button:has-text("Create client")');
    await page.waitForURL(/\/dashboard\/clients\/\d+\?saved=created/, { timeout: 20000 });
    log(`client "${c.name}" created ->`, page.url());
  }

  // 2. One-time client, today: invoice created right away
  await addClient({
    name: "Brightline Dental Clinic", email: "accounts@brightlinedental.ca", phone: "+14165550182",
    timezone: "America/Toronto", address: "88 Queen Street West", city: "Toronto", country: "CA", province: "ON",
    postal: "M5H 2M5", type: "ONE_TIME", service: "Website redesign", amount: "2400", shot: "03-add-client-form",
  });
  await shot(page, "04-client-created");
  const planText = await page.locator("section:has(h2:text('Billing plan'))").innerText();
  log("billing plan card:", planText.replace(/\s+/g, " ").slice(0, 160));

  // 3. Monthly client, date 5 days ahead: scheduled
  const future = new Date(Date.now() + 5 * 86400000).toLocaleDateString("en-CA");
  await addClient({
    name: "Atelier Rousseau", email: "facturation@atelierrousseau.ca", phone: "+15145550147",
    timezone: "America/Toronto", address: "1250 rue Sainte-Catherine Ouest", city: "Montreal", country: "CA",
    province: "QC", postal: "H3G 1P1", type: "MONTHLY", service: "Social media management", amount: "650", date: future,
  });
  const monthly = await page.locator("section:has(h2:text('Billing plan'))").innerText();
  log("monthly plan card:", monthly.replace(/\s+/g, " ").slice(0, 200));
  const atelierUrl = page.url().split("?")[0];

  // 4. Invoices list + live filter (no reload)
  await page.goto(`${BASE}/dashboard/invoices`);
  await shot(page, "05-invoices");
  const rows = await page.locator("tbody tr").allInnerTexts();
  log("invoice rows:", rows.map((r) => r.replace(/\s+/g, " ").slice(0, 90)));
  await page.evaluate(() => (window.__noReload = true));
  await page.fill('input[aria-label="Search"]', "Atelier");
  await page.waitForURL(/q=Atelier/, { timeout: 5000 });
  await page.waitForTimeout(800);
  const still = await page.evaluate(() => window.__noReload === true);
  const filtered = await page.locator("tbody tr").count();
  log(`live search: url=${page.url()} rows=${filtered} no-reload=${still}`);
  await page.selectOption('select[aria-label="Status"]', "PENDING");
  await page.waitForURL(/status=PENDING/, { timeout: 5000 });
  log("live status filter:", page.url(), "no-reload=", await page.evaluate(() => window.__noReload === true));
  await shot(page, "06-invoices-filtered");

  // 5. Edit the monthly plan's amount: old schedule cancelled, new one scheduled
  await page.goto(`${atelierUrl}/edit`);
  await page.fill("#billingAmount", "800");
  await page.click('button:has-text("Save changes")');
  await page.waitForURL(/saved=plan/, { timeout: 20000 });
  log("plan edited ->", page.url());
  const after = await page.locator("section:has(h2:text('Invoices'))").innerText();
  log("atelier invoices after edit:", after.replace(/\s+/g, " ").slice(0, 300));
  await shot(page, "07-plan-edited");

  // 6. Invoice detail and pay page of the first invoice
  await page.goto(`${BASE}/dashboard/invoices/1`);
  await shot(page, "08-invoice-detail");
  await page.goto(`${BASE}/pay/1`);
  await shot(page, "09-pay-page");
  log("pay page button:", await page.locator("button").first().innerText());
} catch (err) {
  console.log("E2E FAILED:", err.message);
  await shot(page, "zz-failure");
  process.exitCode = 1;
} finally {
  await browser.close();
}

