  const atelierUrl = page.url().split("?")[0];

  // 4. Invoices list + live filter (no reload)
  await page.goto(`${BASE}/dashboard/invoices`);
  await shot(page, "05-invoices");
  const rows = await page.locator("tbody tr").allInnerTexts();
  log("invoice rows:", rows.map((r) => r.replace(/\s+/g, " ").slice(0, 90)));
  await page.evaluate(() => (window.__noReload = true));
  await page.fill('input[aria-label="Search"]', "Atelier");
  await page.waitForURL(/q=Atelier/, { timeout: 5000 });
  await page.waitForTimeout(800);
  const still = await page.evaluate(() => window.__noReload === true);
  const filtered = await page.locator("tbody tr").count();
  log(`live search: url=${page.url()} rows=${filtered} no-reload=${still}`);
  await page.selectOption('select[aria-label="Status"]', "PENDING");
  await page.waitForURL(/status=PENDING/, { timeout: 5000 });
  log("live status filter:", page.url(), "no-reload=", await page.evaluate(() => window.__noReload === true));
  await shot(page, "06-invoices-filtered");

  // 5. Edit the monthly plan's amount: old schedule cancelled, new one scheduled
  await page.goto(`${atelierUrl}/edit`);
  await page.fill("#billingAmount", "800");
  await page.click('button:has-text("Save changes")');
  await page.waitForURL(/saved=plan/, { timeout: 20000 });
  log("plan edited ->", page.url());
  const after = await page.locator("section:has(h2:text('Invoices'))").innerText();
  log("atelier invoices after edit:", after.replace(/\s+/g, " ").slice(0, 300));
  await shot(page, "07-plan-edited");

  // 6. Invoice detail and pay page of the first invoice
  await page.goto(`${BASE}/dashboard/invoices/1`);
  await shot(page, "08-invoice-detail");
  await page.goto(`${BASE}/pay/1`);
  await shot(page, "09-pay-page");
  log("pay page button:", await page.locator("button").first().innerText());
} catch (err) {
  console.log("E2E FAILED:", err.message);
  await shot(page, "zz-failure");
  process.exitCode = 1;
} finally {
  await browser.close();
}

