// Monthly plan started today; editing its amount with the same date must be refused,
// and a date next month must be accepted (no double billing).
import { chromium } from "playwright-core";

const BASE = "http://localhost:3012";
const browser = await chromium.launch({ channel: "msedge", headless: true });
const page = await browser.newPage();
try {
  await page.goto(`${BASE}/login`);
  await page.fill("#email", "admin@ledgerly.app");
  await page.fill("#password", "Ledgerly@2026");
  await page.click("button[type=submit]");
  await page.waitForURL("**/dashboard/invoices");

  await page.goto(`${BASE}/dashboard/clients/new`);
  await page.fill("#name", "Guard Test Co");
  await page.fill("#email", "billing@guardtest.ca");
  await page.fill("#phone", "+15145550111");
  await page.fill("#addressLine1", "1 Test Street");
  await page.fill("#city", "Montreal");
  await page.selectOption("#province", "QC");
  await page.fill("#postalCode", "H2X 1Y4");
  await page.click('button:has-text("Recurring (monthly)")');
  await page.fill("#billingDescription", "Hosting");
  await page.fill("#billingAmount", "100");
  await page.click('button:has-text("Create client")');
  await page.waitForURL(/saved=created/, { timeout: 20000 });
  const url = page.url().split("?")[0];
  console.log("created:", url);

  await page.goto(`${url}/edit`);
  await page.fill("#billingAmount", "150");
  await page.click('button:has-text("Save changes")');
  await page.waitForSelector("text=already billed on", { timeout: 15000 });
  console.log("same-date edit refused:", (await page.locator("text=already billed on").innerText()).slice(0, 110));

  const next = new Date();
  next.setMonth(next.getMonth() + 1);
  await page.fill("#billingDate", next.toLocaleDateString("en-CA"));
  await page.click('button:has-text("Save changes")');
  await page.waitForURL(/saved=plan/, { timeout: 20000 });
  const inv = await page.locator("section:has(h2:text('Invoices'))").innerText();
  console.log("after next-month edit:", inv.replace(/\s+/g, " ").slice(0, 260));
} catch (e) {
  console.log("GUARD E2E FAILED:", e.message);
  process.exitCode = 1;
} finally {
  await browser.close();
}

