s=open(p,encoding='utf-8').read()
def rep(a,b):
    global s
    assert s.count(a)==1, a[:60]; s=s.replace(a,b)
rep('''// The billing plan section of the client form. With "NONE" the other
// fields are ignored. That the date is not in the past is checked by the
// action, which knows the client's timezone.''','''// The billing plan section of the client form: every client is billed
// one-time or monthly. That the date is not in the past is checked by the
// action, which knows the client's timezone.''')
rep('''    billingType: z.enum(["NONE", "ONE_TIME", "MONTHLY"], "Choose how this client is billed"),''','''    billingType: z.enum(["ONE_TIME", "MONTHLY"], "Choose one-time or recurring billing"),''')
rep('''    if (v.billingType === "NONE") return;
''','')
rep('''  .transform((v) =>
    v.billingType === "NONE"
      ? { type: "NONE" as const, description: null, amount: null, date: null, termsDays: null }
      : {
          type: v.billingType,
          description: v.billingDescription,
          amount: Number(v.billingAmount).toFixed(2),
          date: v.billingDate,
          termsDays: Number(v.billingTermsDays),
        },
  );''','''  .transform((v) => ({
    type: v.billingType,
    description: v.billingDescription,
    amount: Number(v.billingAmount).toFixed(2),
    date: v.billingDate,
    termsDays: Number(v.billingTermsDays),
