import "dotenv/config";
import { prisma } from "@/lib/db";

// Clears clients and invoices (with everything attached). Admin and settings stay.
async function main() {
  const url = new URL(process.env.DATABASE_URL!);
  if (url.hostname !== "localhost" || !url.pathname.endsWith("/invoice_demo")) throw new Error("Refusing: not the local dev database");
  await prisma.$executeRawUnsafe(
    `TRUNCATE TABLE audit_logs, email_messages, agent_tasks, webhook_events, invoice_taxes, invoice_line_items, invoices, recurring_rules, clients, mock_gateway_invoices RESTART IDENTITY CASCADE`,
  );
  console.log({
    clients: await prisma.client.count(),
    invoices: await prisma.invoice.count(),
    emails: await prisma.emailMessage.count(),
    tasks: await prisma.agentTask.count(),
    admin: await prisma.admin.findMany({ select: { email: true, notificationEmail: true } }),
  });
  await prisma.$disconnect();
}
main().catch((e) => {
  console.error("CLEAR FAILED:", e);
  process.exit(1);
});
EOF
